export const RECRUITMENT_SQL =
  "-- Store de identidade do CANDIDATO, seguindo o schema canonico do better-auth\n-- (padrao OAuth 2.0): CANDIDATES/SESSIONS/ACCOUNTS/VERIFICATIONS ~ user/\n-- session/account/verification. Prefixo de audiencia porque o recrutador e\n-- outra populacao (vem do AD, sem senha local: KONTRATA_RECRUITERS quando\n-- precisar persistir, sem _ACCOUNTS/_VERIFICATIONS).\n--\n-- Convencoes que valem para todas as migrations deste schema: nomes de tabela\n-- nao qualificados (o Oracle resolve para o schema do usuario conectado,\n-- `DB_USER`); PK sempre `NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY`\n-- (`ON NULL`, nao `ALWAYS`, para permitir carga/seed com ID explicito); e\n-- booleano vira `NUMBER(1)` + `CHECK (0,1)` — ou um `TIMESTAMP` nullable\n-- quando a propria data importa (ver EMAIL_VERIFIED_AT abaixo).\n\nCREATE TABLE KONTRATA_CANDIDATES (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  NAME VARCHAR2(255),\n  EMAIL VARCHAR2(255) NOT NULL,\n  EMAIL_VERIFIED_AT TIMESTAMP,\n  IMAGE VARCHAR2(2000),\n  IMAGE_FILE_ID NUMBER,\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CANDIDATES PRIMARY KEY (ID),\n  CONSTRAINT UQ_KONTRATA_CANDIDATES_EMAIL UNIQUE (EMAIL)\n);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATES IS 'Identidade do candidato (schema canonico better-auth: user)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATES.NAME IS 'Nome de exibicao: copia de SOCIAL_NAME ?? LEGAL_NAME (KONTRATA_CANDIDATE_PROFILES); nulo ate o candidato preencher o perfil';\nCOMMENT ON COLUMN KONTRATA_CANDIDATES.EMAIL_VERIFIED_AT IS 'Instante da confirmacao do email; NULL enquanto nao confirmado. Data em vez de flag para provar opt-in e medir o funil de confirmacao';\nCOMMENT ON COLUMN KONTRATA_CANDIDATES.IMAGE IS 'URL do avatar do login social; nula no cadastro por email+senha';\nCOMMENT ON COLUMN KONTRATA_CANDIDATES.IMAGE_FILE_ID IS 'Foto de perfil enviada pelo candidato (arquivo no storage-api); leitura prioriza esta coluna e cai para IMAGE quando nula';\n\n-- Consolida a antiga 0003 (criacao) com o ciclo de vida completo da \"escala\":\n-- as antigas 0009/0017/0018 adicionaram um conjunto grande de colunas de escala\n-- Senior (dia de folga, ratio, jornada, ciclo...) que a antiga 0020 removeu quase\n-- por inteiro, sobrando so SENIOR_ESCALA_CODE — os demais dados (nome, horario,\n-- jornada, ciclo, folga) sao remontados da Senior por\n-- GET /v1/recruiters/senior/escalas/{codigo}. Tambem aplica as antigas 0012\n-- (drop de WORK_SCHEDULE), 0019 (drop de ADDRESS_OVERRIDDEN) e 0022\n-- (SALARY_UNDISCLOSED removida: \"a combinar\" agora e SALARY_MIN e SALARY_MAX\n-- ambos nulos). A antiga 0021 trocou o vocabulario fechado de\n-- KONTRATA_JOB_BENEFITS; so o vocabulario final sobrevive aqui.\n--\n-- Vagas publicadas pelo recrutador. Spec:\n-- docs/superpowers/specs/2026-07-29-cadastro-vagas-design.md\n--\n-- Sem qualificacao de schema: o Oracle resolve para o schema do usuario\n-- conectado (`DB_USER`).\n--\n-- Cada referencia a Senior ocupa DUAS colunas: codigo e snapshot do nome. O\n-- codigo e a chave estavel; o nome e o que estava valendo na publicacao — a\n-- vaga publicada nao muda de titulo sozinha nem exige que a Senior esteja no\n-- ar para ser listada.\n--\n-- Booleanos sao NUMBER(1) com CHECK (0,1): Oracle nao tem o tipo.\n-- CLOB e usado de verdade: descricao de vaga nao cabe com folga em\n-- VARCHAR2(4000) (`fetchAsString = [oracledb.CLOB]` em database.ts).\n\nCREATE TABLE KONTRATA_JOBS (\n  ID                    NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  --\n  TITLE                 VARCHAR2(255)  NOT NULL,\n  --\n  SENIOR_CARGO_CODE     VARCHAR2(30)   NOT NULL,\n  SENIOR_CARGO_NAME     VARCHAR2(255)  NOT NULL,\n  SENIOR_FILIAL_CODE    VARCHAR2(10)   NOT NULL,\n  SENIOR_FILIAL_NAME    VARCHAR2(255)  NOT NULL,\n  SENIOR_SETOR_CODE     VARCHAR2(30),\n  SENIOR_SETOR_NAME     VARCHAR2(255),\n  SENIOR_ESCALA_CODE    VARCHAR2(30),\n  --\n  DESCRIPTION           CLOB,\n  RESPONSIBILITIES      CLOB,\n  REQUIREMENTS          CLOB,\n  BENEFITS_NOTES        CLOB,\n  DIFFERENTIALS         CLOB,\n  --\n  ADDRESS_ZIP           VARCHAR2(8)    NOT NULL,\n  ADDRESS_STREET        VARCHAR2(255)  NOT NULL,\n  ADDRESS_NUMBER        VARCHAR2(20)   NOT NULL,\n  ADDRESS_COMPLEMENT    VARCHAR2(255),\n  ADDRESS_DISTRICT      VARCHAR2(255)  NOT NULL,\n  ADDRESS_CITY          VARCHAR2(255)  NOT NULL,\n  ADDRESS_STATE         CHAR(2)        NOT NULL,\n  -- Geocodificadas em segundo plano após criar/editar a vaga (nunca bloqueia\n  -- o save nem falha por isso — ver `scheduleJobGeocode` em `jobs/service.ts`).\n  -- Uso interno: alimenta o critério objetivo de distância do local de\n  -- trabalho (`infra/matching/criteria/evaluate-profile-field.ts`), nunca\n  -- exposta em contrato público.\n  ADDRESS_LATITUDE      NUMBER,\n  ADDRESS_LONGITUDE     NUMBER,\n  --\n  WORK_SHIFT            VARCHAR2(20)   NOT NULL,\n  --\n  WORK_MODEL            VARCHAR2(20)   NOT NULL,\n  CONTRACT_TYPE         VARCHAR2(20)   NOT NULL,\n  SENIORITY             VARCHAR2(20),\n  OPENINGS              NUMBER(4)      DEFAULT 1 NOT NULL,\n  SALARY_MIN            NUMBER(12,2),\n  SALARY_MAX            NUMBER(12,2),\n  PWD_ELIGIBLE          NUMBER(1)      DEFAULT 0 NOT NULL,\n  APPLICATION_DEADLINE  DATE,\n  INTERNAL_ONLY         NUMBER(1)      DEFAULT 0 NOT NULL,\n  IS_TEMPLATE           NUMBER(1)      DEFAULT 0 NOT NULL,\n  --\n  STATUS                VARCHAR2(20)   DEFAULT 'DRAFT' NOT NULL,\n  PUBLISHED_AT          TIMESTAMP,\n  CLOSED_AT             TIMESTAMP,\n  --\n  -- Autoria vem do JWT do AD, nunca do corpo da requisicao.\n  CREATED_BY            VARCHAR2(100)  NOT NULL,\n  --\n  CREATED_AT            TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,\n  UPDATED_AT            TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,\n  --\n  -- REJECTION_EMAIL_* mora em KONTRATA_JOBS: um unico e-mail de rejeicao por\n  -- vaga, independente de em qual etapa a rejeicao ocorreu.\n  REJECTION_EMAIL_ENABLED NUMBER(1) DEFAULT 0 NOT NULL,\n  REJECTION_EMAIL_SUBJECT VARCHAR2(200),\n  REJECTION_EMAIL_BODY CLOB,\n  --\n  CONSTRAINT PK_KONTRATA_JOBS PRIMARY KEY (ID),\n  --\n  CONSTRAINT CK_JOBS_SHIFT CHECK (\n    WORK_SHIFT IN ('MORNING','AFTERNOON','NIGHT','BUSINESS_HOURS')\n  ),\n  CONSTRAINT CK_JOBS_MODEL CHECK (\n    WORK_MODEL IN ('ON_SITE','HYBRID','REMOTE')\n  ),\n  CONSTRAINT CK_JOBS_CONTRACT CHECK (\n    CONTRACT_TYPE IN ('CLT','INTERMITTENT','INTERNSHIP','APPRENTICE','TEMPORARY','CONTRACTOR')\n  ),\n  CONSTRAINT CK_JOBS_SENIORITY CHECK (\n    SENIORITY IS NULL OR SENIORITY IN ('ENTRY','JUNIOR','MID','SENIOR','LEADERSHIP')\n  ),\n  CONSTRAINT CK_JOBS_STATUS CHECK (\n    STATUS IN ('DRAFT','PUBLISHED','APPLICATIONS_CLOSED','PAUSED','CLOSED')\n  ),\n  CONSTRAINT CK_JOBS_PWD CHECK (PWD_ELIGIBLE IN (0,1)),\n  CONSTRAINT CK_JOBS_INTERNAL_ONLY CHECK (INTERNAL_ONLY IN (0,1)),\n  CONSTRAINT CK_JOBS_IS_TEMPLATE CHECK (IS_TEMPLATE IN (0,1)),\n  CONSTRAINT CK_JOBS_OPENINGS CHECK (OPENINGS >= 1),\n  --\n  -- Teto sem piso nao e faixa: \"ate R$ 8.000, a partir de nada\" nao diz nada\n  -- ao candidato. MAX preenchido exige MIN. Os dois nulos = \"a combinar\".\n  CONSTRAINT CK_JOBS_SALARY_RANGE CHECK (\n    SALARY_MAX IS NULL OR (SALARY_MIN IS NOT NULL AND SALARY_MAX >= SALARY_MIN)\n  ),\n  --\n  -- E esta constraint que concilia rascunho com integridade: DESCRIPTION pode\n  -- ficar nula enquanto a vaga e rascunho, mas o BANCO recusa publicar sem ela.\n  CONSTRAINT CK_JOBS_PUBLISHABLE CHECK (\n    STATUS NOT IN ('PUBLISHED','APPLICATIONS_CLOSED')\n    OR (PUBLISHED_AT IS NOT NULL AND DESCRIPTION IS NOT NULL)\n  ),\n  --\n  -- Simetrica a anterior: vaga encerrada sem saber quando encerrou seria puro\n  -- esquecimento.\n  CONSTRAINT CK_JOBS_CLOSEABLE CHECK (\n    STATUS <> 'CLOSED' OR CLOSED_AT IS NOT NULL\n  ),\n  CONSTRAINT CK_JOBS_REJECTION_EMAIL_ENABLED CHECK (REJECTION_EMAIL_ENABLED IN (0,1))\n);\n\n-- Os quatro filtros da listagem.\nCREATE INDEX IDX_JOBS_STATUS  ON KONTRATA_JOBS (STATUS);\nCREATE INDEX IDX_JOBS_FILIAL  ON KONTRATA_JOBS (SENIOR_FILIAL_CODE);\nCREATE INDEX IDX_JOBS_CARGO   ON KONTRATA_JOBS (SENIOR_CARGO_CODE);\nCREATE INDEX IDX_JOBS_CREATED ON KONTRATA_JOBS (CREATED_AT DESC);\n\nCOMMENT ON TABLE  KONTRATA_JOBS IS 'Vagas cadastradas pelo recrutador no portal interno';\nCOMMENT ON COLUMN KONTRATA_JOBS.SENIOR_CARGO_CODE IS 'R024CAR.CODCAR na base Senior';\nCOMMENT ON COLUMN KONTRATA_JOBS.SENIOR_CARGO_NAME IS 'Snapshot de R024CAR.TITRED na publicacao — nao acompanha renomeacao na Senior';\nCOMMENT ON COLUMN KONTRATA_JOBS.SENIOR_FILIAL_CODE IS 'R030FIL.CODFIL na base Senior';\nCOMMENT ON COLUMN KONTRATA_JOBS.SENIOR_SETOR_CODE IS 'R016ORN.NUMLOC na base Senior';\nCOMMENT ON COLUMN KONTRATA_JOBS.SENIOR_ESCALA_CODE IS 'R006ESC.CODESC da escala da vaga. Unico dado de escala guardado: nome, horario, jornada, ciclo e folga sao remontados da Senior por GET /v1/recruiters/senior/escalas/{codigo}';\nCOMMENT ON COLUMN KONTRATA_JOBS.DESCRIPTION IS 'Nullable para o rascunho existir; CK_JOBS_PUBLISHABLE exige preenchida para publicar';\nCOMMENT ON COLUMN KONTRATA_JOBS.DIFFERENTIALS IS 'Texto livre com os diferenciais da vaga; nullable, sem vocabulario fechado (mesmo tratamento de BENEFITS_NOTES)';\nCOMMENT ON COLUMN KONTRATA_JOBS.ADDRESS_ZIP IS 'Endereco obrigatorio por decisao de negocio, inclusive em rascunho; pre-preenchido a partir da filial';\nCOMMENT ON COLUMN KONTRATA_JOBS.WORK_SHIFT IS 'Turno obrigatorio por decisao de negocio; em varejo e o primeiro filtro do candidato';\nCOMMENT ON COLUMN KONTRATA_JOBS.SENIORITY IS 'Nullable: \"Repositor Pleno\" nao e distincao que o varejo faca';\nCOMMENT ON COLUMN KONTRATA_JOBS.PWD_ELIGIBLE IS '1 = vaga elegivel para pessoa com deficiencia';\nCOMMENT ON COLUMN KONTRATA_JOBS.INTERNAL_ONLY IS '1 = vaga visivel so no portal do recrutador; excluida da listagem e do detalhe publicos em apps/candidatos (ver buildPublicJobWhere)';\nCOMMENT ON COLUMN KONTRATA_JOBS.IS_TEMPLATE IS '1 = vaga marcada pelo recrutador como modelo reutilizavel; nunca visivel ao candidato, so afeta o seletor de \"criar a partir de um modelo\" em vaga nova';\nCOMMENT ON COLUMN KONTRATA_JOBS.CREATED_BY IS 'sAMAccountName do recrutador, extraido do JWT do AD';\n\nCOMMENT ON COLUMN KONTRATA_JOBS.REJECTION_EMAIL_ENABLED IS '1 = envia e-mail automatico ao candidato quando a candidatura desta vaga e rejeitada, em qualquer etapa';\nCOMMENT ON COLUMN KONTRATA_JOBS.REJECTION_EMAIL_SUBJECT IS 'Assunto do e-mail de rejeicao, texto livre com variaveis {{candidato}}/{{vaga}}; NULL quando desabilitado';\nCOMMENT ON COLUMN KONTRATA_JOBS.REJECTION_EMAIL_BODY IS 'Corpo do e-mail de rejeicao, texto livre com variaveis {{candidato}}/{{vaga}}; NULL quando desabilitado';\n\n-- Catalogo de etapas do motor unificado, com requisitos por etapa.\n\nCREATE TABLE KONTRATA_STAGE (\n  ID                   NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  NAME                 VARCHAR2(80)  NOT NULL,\n  DESCRIPTION          VARCHAR2(400) NOT NULL,\n  VISIBLE_TO_CANDIDATE NUMBER(1) DEFAULT 1 NOT NULL,\n  CREATED_BY           VARCHAR2(100) NOT NULL,\n  CREATED_AT           TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_BY           VARCHAR2(100),\n  UPDATED_AT           TIMESTAMP,\n  DELETED_BY           VARCHAR2(100),\n  DELETED_AT           TIMESTAMP,\n  PINNED_POSITION      NUMBER,\n  STAGE_KIND           VARCHAR2(20) DEFAULT 'NORMAL' NOT NULL CHECK (STAGE_KIND IN ('NORMAL','PREREQUISITES')),\n  SYSTEM_KEY           VARCHAR2(40),\n  CONSTRAINT PK_KONTRATA_STAGE PRIMARY KEY (ID),\n  CONSTRAINT CK_STAGE_VISIBLE CHECK (VISIBLE_TO_CANDIDATE IN (0, 1)),\n  CONSTRAINT CK_STAGE_PINNED_NONZERO CHECK (PINNED_POSITION != 0 OR PINNED_POSITION IS NULL)\n);\n\nCREATE UNIQUE INDEX UQ_STAGE_NAME ON KONTRATA_STAGE (UPPER(NAME));\nCREATE UNIQUE INDEX UQ_STAGE_PINNED_POSITION ON KONTRATA_STAGE (PINNED_POSITION);\nCREATE UNIQUE INDEX UQ_STAGE_SYSTEM_KEY ON KONTRATA_STAGE (SYSTEM_KEY);\n\nCOMMENT ON TABLE KONTRATA_STAGE IS 'Catalogo global de etapas, reutilizavel pelas vagas';\nCOMMENT ON COLUMN KONTRATA_STAGE.DELETED_AT IS 'Nula = ativa; preenchida = soft-deletada';\nCOMMENT ON COLUMN KONTRATA_STAGE.PINNED_POSITION IS 'Posicao fixa no fluxo por sinal: positivo = a partir do inicio (1=primeira), negativo = a partir do fim (-1=ultima). NULL = etapa livre (miolo).';\nCOMMENT ON COLUMN KONTRATA_STAGE.STAGE_KIND IS\n  'NORMAL = checklist generico; PREREQUISITES = checklist dinamico de KONTRATA_JOB_CRITERION. No maximo uma linha PREREQUISITES.';\nCOMMENT ON COLUMN KONTRATA_STAGE.SYSTEM_KEY IS\n  'Marca estavel de etapa que o sistema referencia por codigo (ex. ANALISE_MATRIZ). NULL = etapa comum. Etapa marcada nao pode ser renomeada nem excluida.';\n\n-- Catálogo normalizado de habilidades (substitui o antigo\n-- KONTRATA_CANDIDATE_PROFILES.SKILLS em JSON). O backfill que a antiga 0023\n-- fazia a partir daquela coluna não entra aqui: ela nunca existe neste estado\n-- final consolidado (foi adicionada e removida antes de chegar a este ponto),\n-- e o backfill só fazia sentido migrando linhas que já existiam num ambiente\n-- específico.\n\nCREATE TABLE KONTRATA_SKILL_GROUPS (\n  ID         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  NAME       VARCHAR2(60)  NOT NULL,\n  CREATED_BY VARCHAR2(100) NOT NULL,\n  CREATED_AT TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_BY VARCHAR2(100),\n  UPDATED_AT TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  DELETED_BY VARCHAR2(100),\n  DELETED_AT TIMESTAMP,\n  CONSTRAINT PK_KONTRATA_SKILL_GROUPS PRIMARY KEY (ID)\n);\n\nCREATE UNIQUE INDEX UQ_SKILL_GROUPS_NAME\n  ON KONTRATA_SKILL_GROUPS (CASE WHEN DELETED_AT IS NULL THEN UPPER(NAME) END);\n\nCOMMENT ON TABLE KONTRATA_SKILL_GROUPS IS 'Grupos do catálogo de habilidades, mantidos pelo recrutador';\n\n-- Catálogo global de critérios de avaliação de candidato numa vaga. Substitui\n-- KONTRATA_PREREQUISITE e KONTRATA_JOB_CRITERIA num modelo só.\n--\n-- VALUE_MODE diz de onde vem o valor avaliado; CONFIG carrega a configuração\n-- específica do modo (validada por Zod, não pelo banco). Só CATALOG_QUESTION é\n-- criável pelo painel — PROFILE_FIELD e INSTRUMENT apontam para avaliador em\n-- código e são seedados.\n--\n-- Spec: docs/superpowers/specs/2026-09-04-criterios-unificados-design.md\nCREATE TABLE KONTRATA_CRITERION (\n  ID                     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  LABEL                  VARCHAR2(400) NOT NULL,\n  VALUE_MODE             VARCHAR2(20) NOT NULL,\n  ANSWER_SCOPE           VARCHAR2(20) NOT NULL,\n  CONFIG                 CLOB NOT NULL CHECK (CONFIG IS JSON),\n  DESCRIPTION            CLOB,\n  VALIDITY_MONTHS        NUMBER(3),\n  DEFAULT_WEIGHT         NUMBER(3) DEFAULT 0 NOT NULL,\n  DEFAULT_BLOCKS_ADVANCE NUMBER(1) DEFAULT 1 NOT NULL,\n  DEFAULT_AFFECTS_SCORE  NUMBER(1) DEFAULT 0 NOT NULL,\n  CREATED_BY VARCHAR2(100) NOT NULL,\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_BY VARCHAR2(100),\n  UPDATED_AT TIMESTAMP,\n  DELETED_BY VARCHAR2(100),\n  DELETED_AT TIMESTAMP,\n  CONSTRAINT PK_CRITERION PRIMARY KEY (ID),\n  CONSTRAINT CK_CRITERION_MODE  CHECK (VALUE_MODE IN ('CATALOG_QUESTION','PROFILE_FIELD','INSTRUMENT')),\n  CONSTRAINT CK_CRITERION_SCOPE CHECK (ANSWER_SCOPE IN ('CANDIDATE','APPLICATION')),\n  -- validade só faz sentido no que é reaproveitado entre vagas\n  CONSTRAINT CK_CRITERION_VALIDITY CHECK (VALIDITY_MONTHS IS NULL OR ANSWER_SCOPE = 'CANDIDATE'),\n  CONSTRAINT CK_CRITERION_WEIGHT CHECK (DEFAULT_WEIGHT BETWEEN 0 AND 100)\n);\n\nCOMMENT ON TABLE KONTRATA_CRITERION IS 'Catalogo global de criterios (pergunta, campo de perfil ou instrumento)';\nCOMMENT ON COLUMN KONTRATA_CRITERION.VALUE_MODE IS 'CATALOG_QUESTION | PROFILE_FIELD | INSTRUMENT — de onde vem o valor avaliado';\nCOMMENT ON COLUMN KONTRATA_CRITERION.ANSWER_SCOPE IS 'CANDIDATE = reaproveitada entre vagas; APPLICATION = one-shot por candidatura';\nCOMMENT ON COLUMN KONTRATA_CRITERION.CONFIG IS 'JSON por modo: options+score | field+zones | instrument';\nCOMMENT ON COLUMN KONTRATA_CRITERION.DESCRIPTION IS 'Texto de apoio só para o recrutador, explicando para que o critério serve — nunca chega ao candidato';\n\nCREATE TABLE KONTRATA_CANDIDATE_ACCOUNTS (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  USER_ID NUMBER NOT NULL,\n  ACCOUNT_ID VARCHAR2(255) NOT NULL,\n  PROVIDER_ID VARCHAR2(64) NOT NULL,\n  ACCESS_TOKEN VARCHAR2(4000),\n  REFRESH_TOKEN VARCHAR2(4000),\n  ACCESS_TOKEN_EXPIRES_AT TIMESTAMP,\n  REFRESH_TOKEN_EXPIRES_AT TIMESTAMP,\n  SCOPE VARCHAR2(2000),\n  ID_TOKEN VARCHAR2(4000),\n  \"PASSWORD\" VARCHAR2(255),\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CANDIDATE_ACCOUNTS PRIMARY KEY (ID),\n  CONSTRAINT FK_KONTRATA_CANDIDATE_ACCOUNTS_USER FOREIGN KEY (USER_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE\n);\n\n-- Cobrem: join por dono, lookup de login por (provider, account).\nCREATE INDEX IX_KONTRATA_CANDIDATE_ACCOUNTS_USER_ID ON KONTRATA_CANDIDATE_ACCOUNTS (USER_ID);\nCREATE INDEX IX_KONTRATA_CANDIDATE_ACCOUNTS_PROVIDER_ACCOUNT ON KONTRATA_CANDIDATE_ACCOUNTS (PROVIDER_ID, ACCOUNT_ID);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_ACCOUNTS IS 'Credenciais de login do candidato, local ou social (schema canonico better-auth: account)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_ACCOUNTS.ACCOUNT_ID IS 'Identificador junto ao provedor: email normalizado em credential, sub do provedor em login social';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_ACCOUNTS.ACCESS_TOKEN IS 'Campos de provedor OAuth2/OIDC, nulos enquanto credential for o unico provedor; VARCHAR2(4000) e nao CLOB para ficar indexavel e falhar alto (ORA-12899) em vez de truncar em silencio';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_ACCOUNTS.\"PASSWORD\" IS 'Hash argon2id, nunca texto puro; nula para provedores sociais. Nome exige aspas nas queries por ser palavra reservada';\n\nCREATE TABLE KONTRATA_CANDIDATE_SESSIONS (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  USER_ID NUMBER NOT NULL,\n  TOKEN VARCHAR2(255) NOT NULL,\n  EXPIRES_AT TIMESTAMP NOT NULL,\n  IP_ADDRESS VARCHAR2(64),\n  USER_AGENT VARCHAR2(1000),\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CANDIDATE_SESSIONS PRIMARY KEY (ID),\n  CONSTRAINT UQ_KONTRATA_CANDIDATE_SESSIONS_TOKEN UNIQUE (TOKEN),\n  CONSTRAINT FK_KONTRATA_CANDIDATE_SESSIONS_USER FOREIGN KEY (USER_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE\n);\n\nCREATE INDEX IX_KONTRATA_CANDIDATE_SESSIONS_USER_ID ON KONTRATA_CANDIDATE_SESSIONS (USER_ID);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_SESSIONS IS 'Sessoes do candidato (schema canonico better-auth: session)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_SESSIONS.TOKEN IS 'Credencial de sessao do better-auth; a autenticacao real e por JWT, coluna mantida por compatibilidade de schema';\n\nCREATE TABLE KONTRATA_CANDIDATE_VERIFICATIONS (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  IDENTIFIER VARCHAR2(255) NOT NULL,\n  VALUE VARCHAR2(255) NOT NULL,\n  EXPIRES_AT TIMESTAMP NOT NULL,\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CANDIDATE_VERIFICATIONS PRIMARY KEY (ID)\n);\n\n-- As duas formas de acesso a token de verificacao (por valor no consumo, por\n-- identifier na invalidacao).\nCREATE INDEX IX_KONTRATA_CANDIDATE_VERIFICATIONS_VALUE ON KONTRATA_CANDIDATE_VERIFICATIONS (VALUE);\nCREATE INDEX IX_KONTRATA_CANDIDATE_VERIFICATIONS_IDENTIFIER ON KONTRATA_CANDIDATE_VERIFICATIONS (IDENTIFIER);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_VERIFICATIONS IS 'Tokens de verificacao de email / reset de senha (schema canonico better-auth: verification)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_VERIFICATIONS.IDENTIFIER IS 'Namespaced como verify:{email} ou reset:{email}, para cada consumidor recusar token emitido para o outro proposito';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_VERIFICATIONS.VALUE IS 'SHA-256 hex do token (o token cru so viaja no link do e-mail)';\n\n-- Dados cadastrais do candidato: uma linha por conta, criada na primeira vez\n-- que ele salva qualquer campo do perfil. Consolida as antigas 0002 (criacao) +\n-- 0004 (nacionalidade livre, SKILLS) + 0024 (drop de SKILLS) + 0029\n-- (MARITAL_STATUS). SKILLS nunca existe neste estado final (foi adicionada e\n-- removida no meio do caminho — o catalogo normalizado e\n-- KONTRATA_SKILLS/KONTRATA_CANDIDATE_SKILLS).\n--\n-- Toda coluna de dominio e NULLABLE de proposito: o perfil salva parcial. Sem\n-- CHECK nos conjuntos fechados (PRONOUN, GENDER_IDENTITY, RACE,\n-- MARITAL_STATUS): a validacao mora no Zod da rota. HAS_DISABILITY mantem\n-- CHECK por ser booleano, nao enum.\n\nCREATE TABLE KONTRATA_CANDIDATE_PROFILES (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  USER_ID NUMBER NOT NULL,\n  --\n  -- Dados pessoais\n  LEGAL_NAME VARCHAR2(255),\n  SOCIAL_NAME VARCHAR2(255),\n  NATIONALITY VARCHAR2(60),\n  PRONOUN VARCHAR2(32),\n  BIRTH_DATE DATE,\n  CPF VARCHAR2(11),\n  MARITAL_STATUS VARCHAR2(20),\n  PHONE VARCHAR2(15),\n  LINKEDIN_URL VARCHAR2(2000),\n  INSTAGRAM_URL VARCHAR2(2000),\n  FACEBOOK_URL VARCHAR2(2000),\n  X_URL VARCHAR2(2000),\n  HAS_DRIVERS_LICENSE      NUMBER(1),\n  DRIVERS_LICENSE_CATEGORY VARCHAR2(4),\n  HAS_OWN_VEHICLE          NUMBER(1),\n  --\n  -- Dados exigidos pela Senior na admissao (spec 2026-09-30 admissao-senior)\n  SEX CHAR(1),\n  EDUCATION_LEVEL NUMBER(2),\n  BIRTH_COUNTRY_CODE NUMBER(4),\n  BIRTH_STATE VARCHAR2(2),\n  BIRTH_CITY_IBGE_CODE NUMBER(7),\n  BIRTH_CITY_NAME VARCHAR2(120),\n  --\n  -- Responsavel legal e e-mail escolar (menor de idade, ver BIRTH_DATE)\n  GUARDIAN_NAME VARCHAR2(150),\n  GUARDIAN_PHONE VARCHAR2(20),\n  GUARDIAN_EMAIL VARCHAR2(255),\n  SCHOOL_EMAIL VARCHAR2(255),\n  --\n  -- Endereco\n  POSTAL_CODE VARCHAR2(8),\n  STREET VARCHAR2(255),\n  STREET_TYPE VARCHAR2(4),\n  STREET_NUMBER VARCHAR2(20),\n  COMPLEMENT VARCHAR2(100),\n  NEIGHBORHOOD VARCHAR2(120),\n  CITY VARCHAR2(120),\n  CITY_IBGE_CODE NUMBER(7),\n  STATE VARCHAR2(2),\n  COUNTRY VARCHAR2(2) DEFAULT 'BR',\n  -- Geocodificadas em segundo plano após salvar o endereço (nunca bloqueia o\n  -- save nem falha por isso — ver `scheduleProfileGeocode` em\n  -- `candidates/profile/service.ts`). Uso interno: alimenta o critério\n  -- objetivo de distância do local de trabalho\n  -- (`infra/matching/criteria/evaluate-profile-field.ts`),\n  -- nunca exposta em contrato público.\n  LATITUDE NUMBER,\n  LONGITUDE NUMBER,\n  --\n  -- Diversidade e inclusao\n  GENDER_IDENTITY VARCHAR2(32),\n  SEXUAL_ORIENTATION VARCHAR2(32),\n  RACE VARCHAR2(24),\n  HAS_DISABILITY NUMBER(1),\n  DISABILITY_TYPES VARCHAR2(200),\n  DISABILITY_DETAILS VARCHAR2(500),\n  DIVERSITY_CONSENT_AT TIMESTAMP,\n  --\n  -- Vinculo com o Grupo Koch: snapshot da Senior por CPF, pra filtrar a\n  -- listagem sem consultar outro banco (ver `v1/shared/employment-status.ts`).\n  EMPLOYMENT_STATUS VARCHAR2(20),\n  EMPLOYMENT_CHECKED_AT TIMESTAMP,\n  --\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  --\n  CONSTRAINT PK_KONTRATA_CANDIDATE_PROFILES PRIMARY KEY (ID),\n  CONSTRAINT UQ_KONTRATA_CANDIDATE_PROFILES_USER UNIQUE (USER_ID),\n  CONSTRAINT UQ_KONTRATA_CANDIDATE_PROFILES_CPF UNIQUE (CPF),\n  CONSTRAINT CK_KONTRATA_CANDIDATE_PROFILES_DISABILITY CHECK (HAS_DISABILITY IN (0, 1)),\n  CONSTRAINT FK_KONTRATA_CANDIDATE_PROFILES_USER FOREIGN KEY (USER_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE\n);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_PROFILES IS 'Dados cadastrais de dominio do candidato; identidade fica em KONTRATA_CANDIDATES';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.STREET_NUMBER IS 'VARCHAR2 e nao numerico: existe \"s/n\". Nome evita a coluna NUMBER, que exigiria aspas por ser tipo do Oracle';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.BIRTH_DATE IS 'DATE; atravessa a borda HTTP como texto (TO_CHAR/TO_DATE) para nao depender do fuso do processo';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.CPF IS 'UNIQUE mesmo nullable: Oracle nao indexa NULL em indice unico, entao perfis sem CPF convivem';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.DIVERSITY_CONSENT_AT IS 'Consentimento LGPD art. 11 para o bloco sensivel (GENDER_IDENTITY, SEXUAL_ORIENTATION, RACE, HAS_DISABILITY, DISABILITY_TYPES, DISABILITY_DETAILS); retirar zera esta e as seis colunas';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.MARITAL_STATUS IS 'SOLTEIRO|CASADO|UNIAO_ESTAVEL|DIVORCIADO|SEPARADO|VIUVO; conjunto fechado no Zod';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.GUARDIAN_NAME IS 'Nome do responsavel legal — so relevante quando o candidato e menor de idade (ver BIRTH_DATE)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.SCHOOL_EMAIL IS 'E-mail escolar — estagio/aprendiz menor de idade';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.DRIVERS_LICENSE_CATEGORY IS 'A | B | AB | C | D | E — so preenchido quando HAS_DRIVERS_LICENSE = 1';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.EMPLOYMENT_STATUS IS 'ATIVO|EX_COLABORADOR|SEM_VINCULO, snapshot da Senior pelo CPF. NULL = sem CPF ou ainda nao consultado';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.SEX IS 'M|F, sexo como o eSocial pede (R034FUN.TIPSEX); distinto de GENDER_IDENTITY';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.EDUCATION_LEVEL IS 'Codigo R022GRA da Senior (grau de instrucao)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.BIRTH_COUNTRY_CODE IS 'Codigo R074PAI (1 = Brasil)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.STREET_TYPE IS 'Codigo LTipLgd da Senior (R, AV, AL...)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILES.CITY_IBGE_CODE IS 'Codigo IBGE da cidade, que e o R074CID.CODCID da Senior; vem do CEP';\n\n-- Curriculo do candidato: quatro listas 1:N por conta (formacao, experiencia,\n-- idiomas, conquistas). Tabelas-filhas com ON DELETE CASCADE. Sem CHECK nos\n-- conjuntos fechados (vivem no Zod) — so IS_CURRENT mantem CHECK por ser\n-- booleano. Datas mes/ano como VARCHAR2(7) 'YYYY-MM' (curriculo nao tem dia; e\n-- VARCHAR evita o bug de fuso do DATE). A ordem da lista e a ordem de\n-- insercao: cada save e um replace (delete-all + insert na ordem do array),\n-- entao ORDER BY ID reconstroi a ordem da tela — sem coluna de indice dedicada.\n\nCREATE TABLE KONTRATA_CANDIDATE_EDUCATION (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  USER_ID NUMBER NOT NULL,\n  EDUCATION_LEVEL VARCHAR2(16),\n  DEGREE VARCHAR2(20),\n  STATUS VARCHAR2(16),\n  INSTITUTION VARCHAR2(255),\n  COURSE VARCHAR2(255),\n  START_MONTH VARCHAR2(7),\n  END_MONTH VARCHAR2(7),\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CAND_EDUCATION PRIMARY KEY (ID),\n  CONSTRAINT FK_KONTRATA_CAND_EDUCATION_USER FOREIGN KEY (USER_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE\n);\n\nCREATE INDEX IX_KONTRATA_CAND_EDUCATION_USER ON KONTRATA_CANDIDATE_EDUCATION (USER_ID);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_EDUCATION IS 'Formacao academica do curriculo (lista 1:N por candidato)';\n\nCREATE TABLE KONTRATA_CANDIDATE_EXPERIENCE (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  USER_ID NUMBER NOT NULL,\n  COMPANY VARCHAR2(255),\n  ROLE VARCHAR2(255),\n  IS_CURRENT NUMBER(1) DEFAULT 0 NOT NULL,\n  START_MONTH VARCHAR2(7),\n  END_MONTH VARCHAR2(7),\n  DESCRIPTION CLOB,\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CAND_EXPERIENCE PRIMARY KEY (ID),\n  CONSTRAINT CK_KONTRATA_CAND_EXPERIENCE_CURRENT CHECK (IS_CURRENT IN (0, 1)),\n  CONSTRAINT FK_KONTRATA_CAND_EXPERIENCE_USER FOREIGN KEY (USER_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE\n);\n\nCREATE INDEX IX_KONTRATA_CAND_EXPERIENCE_USER ON KONTRATA_CANDIDATE_EXPERIENCE (USER_ID);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_EXPERIENCE IS 'Experiencia profissional do curriculo (lista 1:N por candidato)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_EXPERIENCE.DESCRIPTION IS 'CLOB e nao VARCHAR2(2000): sob CHAR semantics o VARCHAR2 ainda esbarra no teto fisico de 4000 bytes; o limite de 2000 caracteres que o candidato ve na tela e do Zod';\n\nCREATE TABLE KONTRATA_CANDIDATE_LANGUAGES (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  USER_ID NUMBER NOT NULL,\n  LANGUAGE VARCHAR2(60),\n  PROFICIENCY VARCHAR2(16),\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CAND_LANGUAGES PRIMARY KEY (ID),\n  CONSTRAINT FK_KONTRATA_CAND_LANGUAGES_USER FOREIGN KEY (USER_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE\n);\n\nCREATE INDEX IX_KONTRATA_CAND_LANGUAGES_USER ON KONTRATA_CANDIDATE_LANGUAGES (USER_ID);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_LANGUAGES IS 'Idiomas do curriculo (lista 1:N por candidato)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_LANGUAGES.PROFICIENCY IS 'Nome evita a coluna LEVEL, palavra reservada no Oracle (ORA-03050)';\n\nCREATE TABLE KONTRATA_CANDIDATE_ACHIEVEMENTS (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  USER_ID NUMBER NOT NULL,\n  ACHIEVEMENT_TYPE VARCHAR2(20),\n  TITLE VARCHAR2(255),\n  DESCRIPTION CLOB,\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CAND_ACHIEVEMENTS PRIMARY KEY (ID),\n  CONSTRAINT FK_KONTRATA_CAND_ACHIEVEMENTS_USER FOREIGN KEY (USER_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE\n);\n\nCREATE INDEX IX_KONTRATA_CAND_ACHIEVEMENTS_USER ON KONTRATA_CANDIDATE_ACHIEVEMENTS (USER_ID);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_ACHIEVEMENTS IS 'Conquistas/premios do curriculo (lista 1:N por candidato)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_ACHIEVEMENTS.DESCRIPTION IS 'CLOB pelo mesmo motivo de KONTRATA_CANDIDATE_EXPERIENCE.DESCRIPTION';\n\n-- Registro da SOLICITACAO de verificacao de antecedentes (LiberadoApp), por\n-- candidato. NUNCA grava o resultado da consulta em si — dado sensivel\n-- (ECA art. 143 / CLT art. 428), sempre lido ao vivo da LiberadoApp. So o\n-- \"quem/quando pediu\" e o id da pessoa na LiberadoApp (pra nao recadastrar\n-- a cada consulta) ficam aqui.\nCREATE TABLE KONTRATA_CANDIDATE_VERIFICACAO (\n  CANDIDATE_ID       NUMBER        NOT NULL,\n  LIBERADO_PERSON_ID VARCHAR2(100),\n  STATUS             VARCHAR2(20)  DEFAULT 'SOLICITADA' NOT NULL,\n  REQUESTED_BY       VARCHAR2(100) NOT NULL,\n  REQUESTED_BY_NAME  VARCHAR2(255),\n  REQUESTED_AT       TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_CANDIDATE_VERIFICACAO PRIMARY KEY (CANDIDATE_ID),\n  CONSTRAINT FK_CANDIDATE_VERIFICACAO_CAND FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE\n);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_VERIFICACAO IS 'Registro de solicitacao de verificacao de antecedentes (LiberadoApp) - nunca o resultado';\n\n-- Cache do resumo de historico funcional gerado por IA (4 campos\n-- narrativos), por candidato. Sem seed em nenhuma etapa de proposito: a\n-- geracao custa uma chamada de IA, entao o painel so aparece onde alguem\n-- habilitar deliberadamente pelo catalogo (ver\n-- docs/superpowers/specs/2026-09-01-resumo-historico-panel-design.md).\nCREATE TABLE KONTRATA_CANDIDATE_HISTORICO_RESUMO (\n  CANDIDATE_ID          NUMBER         NOT NULL,\n  PENALIDADES           VARCHAR2(1000) NOT NULL,\n  ATESTADOS             VARCHAR2(1000) NOT NULL,\n  AFASTAMENTOS          VARCHAR2(1000) NOT NULL,\n  ANOTACAO_DESLIGAMENTO VARCHAR2(1000),\n  MODEL                 VARCHAR2(100)  NOT NULL,\n  GENERATED_AT          TIMESTAMP      DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_CANDIDATE_HISTORICO_RESUMO PRIMARY KEY (CANDIDATE_ID),\n  CONSTRAINT FK_CANDIDATE_HISTORICO_RESUMO_CAND FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE\n);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_HISTORICO_RESUMO IS 'Cache do resumo de historico funcional gerado por IA (4 campos narrativos), advisory, regeneravel';\n\n-- Análise por IA de um processo judicial (Verificação de Antecedentes, Fase\n-- 2). Única tabela desta feature que persiste um RESULTADO (cifrado) em vez\n-- de só o registro de solicitação — ver spec Fase 2 para o motivo: o\n-- resultado é derivado (a interpretação da LLM), nunca o payload bruto da\n-- LiberadoApp, e fica cifrado por carregar resumo de processo judicial de\n-- terceiros.\nCREATE TABLE KONTRATA_CANDIDATE_ANALISE_PROCESSO (\n  CANDIDATE_ID              NUMBER        NOT NULL,\n  NUMERO_PROCESSO           VARCHAR2(30)  NOT NULL,\n  STATUS                    VARCHAR2(20)  NOT NULL, -- PRONTA | INDISPONIVEL | ERRO\n  ANALISE_ENCRYPTED         CLOB,                    -- só quando STATUS = PRONTA\n  MODEL                     VARCHAR2(60),\n  ULTIMA_MOVIMENTACAO_ANALISADA VARCHAR2(30),\n  REQUESTED_BY              VARCHAR2(100) NOT NULL,\n  REQUESTED_BY_NAME         VARCHAR2(255),\n  GENERATED_AT              TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_CANDIDATE_ANALISE_PROCESSO PRIMARY KEY (CANDIDATE_ID, NUMERO_PROCESSO),\n  CONSTRAINT FK_CANDIDATE_ANALISE_PROCESSO_CAND FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE\n);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_ANALISE_PROCESSO IS 'Análise por IA de um processo judicial (cifrada) — única tabela da Verificação de Antecedentes que persiste resultado, não só solicitação; ver spec Fase 2 para o motivo';\n\nCREATE TABLE KONTRATA_SKILLS (\n  ID         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  NAME       VARCHAR2(40)  NOT NULL,\n  GROUP_ID   NUMBER        NOT NULL,\n  CREATED_BY VARCHAR2(100) NOT NULL,\n  CREATED_AT TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_BY VARCHAR2(100),\n  UPDATED_AT TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  DELETED_BY VARCHAR2(100),\n  DELETED_AT TIMESTAMP,\n  CONSTRAINT PK_KONTRATA_SKILLS PRIMARY KEY (ID),\n  CONSTRAINT FK_SKILLS_GROUP FOREIGN KEY (GROUP_ID)\n    REFERENCES KONTRATA_SKILL_GROUPS (ID)\n);\n\nCREATE UNIQUE INDEX UQ_SKILLS_NAME\n  ON KONTRATA_SKILLS (CASE WHEN DELETED_AT IS NULL THEN UPPER(NAME) END);\nCREATE INDEX IDX_SKILLS_GROUP ON KONTRATA_SKILLS (GROUP_ID);\n\nCOMMENT ON TABLE KONTRATA_SKILLS IS 'Habilidades selecionáveis pelo candidato, mantidas pelo recrutador';\nCOMMENT ON COLUMN KONTRATA_SKILLS.DELETED_AT IS 'Delete lógico: a habilidade sai das telas, o vínculo em KONTRATA_CANDIDATE_SKILLS permanece';\n\nCREATE TABLE KONTRATA_JOB_BENEFITS (\n  JOB_ID        NUMBER        NOT NULL,\n  BENEFIT_CODE  VARCHAR2(30)  NOT NULL,\n  --\n  CONSTRAINT PK_KONTRATA_JOB_BENEFITS PRIMARY KEY (JOB_ID, BENEFIT_CODE),\n  CONSTRAINT FK_JOB_BENEFITS_JOB FOREIGN KEY (JOB_ID)\n    REFERENCES KONTRATA_JOBS (ID) ON DELETE CASCADE,\n  CONSTRAINT CK_JOB_BENEFITS_CODE CHECK (\n    BENEFIT_CODE IN (\n      'TRANSPORTE','ALIMENTACAO','SAUDE','ODONTOLOGICO','TELEMEDICINA',\n      'FARMACIA','SEGURO_VIDA','PLR','CRECHE','AUXILIO_EDUCACAO'\n    )\n  )\n);\n\nCOMMENT ON TABLE KONTRATA_JOB_BENEFITS IS 'Beneficios de uma vaga, vocabulario fechado; tabela filha (nao CLOB) para permitir chip filtravel no portal do candidato. O que nao couber no vocabulario vai em KONTRATA_JOBS.BENEFITS_NOTES';\n\nCREATE TABLE KONTRATA_STAGE_REQUIREMENT (\n  ID               NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  STAGE_ID         NUMBER NOT NULL,\n  POSITION         NUMBER NOT NULL,\n  REQUIREMENT_TYPE VARCHAR2(30) NOT NULL,\n  -- KIND formaliza em KONTRATA_STAGE_REQUIREMENT uma distincao que ja era\n  -- implicita: qual requisito TRAVA avanco (ACTIONABLE, os 9 tipos de hoje) e\n  -- qual so APARECE no front, sem cumprimento (DISPLAY). Spec:\n  -- docs/superpowers/specs/2026-08-31-dossie-candidato-analise-matriz-design.md\n  KIND VARCHAR2(20) DEFAULT 'ACTIONABLE' NOT NULL,\n  CONSTRAINT PK_STAGE_REQUIREMENT PRIMARY KEY (ID),\n  CONSTRAINT FK_STAGE_REQ_STAGE FOREIGN KEY (STAGE_ID)\n    REFERENCES KONTRATA_STAGE (ID) ON DELETE CASCADE,\n  CONSTRAINT UQ_STAGE_REQ_POSITION UNIQUE (STAGE_ID, POSITION),\n  CONSTRAINT UQ_STAGE_REQ_TYPE UNIQUE (STAGE_ID, REQUIREMENT_TYPE),\n  CONSTRAINT CK_STAGE_REQ_KIND CHECK (KIND IN ('ACTIONABLE', 'DISPLAY'))\n);\n\nCOMMENT ON TABLE KONTRATA_STAGE_REQUIREMENT IS 'O que a etapa exige; REQUIREMENT_TYPE decide UI e avanco (enum no codigo)';\nCOMMENT ON COLUMN KONTRATA_STAGE_REQUIREMENT.KIND IS 'ACTIONABLE trava avanco (canAdvance); DISPLAY so aparece no front e nunca e cumprido';\n\n-- Fluxos padrao: sequencia nomeada e reutilizavel de etapas (ancoras +\n-- miolo), que o recrutador pode aplicar ao montar o fluxo de uma vaga.\n-- Spec: docs/superpowers/specs/2026-09-01-fluxos-padrao-design.md\nCREATE TABLE KONTRATA_STAGE_FLOW (\n  ID          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  NAME        VARCHAR2(80)  NOT NULL,\n  DESCRIPTION VARCHAR2(400) NOT NULL,\n  CREATED_BY  VARCHAR2(100) NOT NULL,\n  CREATED_AT  TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_BY  VARCHAR2(100),\n  UPDATED_AT  TIMESTAMP,\n  CONSTRAINT PK_KONTRATA_STAGE_FLOW PRIMARY KEY (ID)\n);\n\nCREATE UNIQUE INDEX UQ_STAGE_FLOW_NAME ON KONTRATA_STAGE_FLOW (UPPER(NAME));\n\nCOMMENT ON TABLE KONTRATA_STAGE_FLOW IS 'Fluxos padrao nomeados e reutilizaveis, aplicados manualmente ao criar uma vaga';\n\nCREATE TABLE KONTRATA_CANDIDATE_SKILLS (\n  CANDIDATE_ID NUMBER    NOT NULL,\n  SKILL_ID     NUMBER    NOT NULL,\n  CREATED_AT   TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CANDIDATE_SKILLS PRIMARY KEY (CANDIDATE_ID, SKILL_ID),\n  CONSTRAINT FK_CAND_SKILLS_CANDIDATE FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_CAND_SKILLS_SKILL FOREIGN KEY (SKILL_ID)\n    REFERENCES KONTRATA_SKILLS (ID)\n);\n\nCREATE INDEX IDX_CAND_SKILLS_SKILL ON KONTRATA_CANDIDATE_SKILLS (SKILL_ID);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_SKILLS IS 'Habilidades marcadas por um candidato';\n\nCREATE TABLE KONTRATA_JOB_SKILLS (\n  JOB_ID   NUMBER NOT NULL,\n  SKILL_ID NUMBER NOT NULL,\n  CONSTRAINT PK_KONTRATA_JOB_SKILLS PRIMARY KEY (JOB_ID, SKILL_ID),\n  CONSTRAINT FK_JOB_SKILLS_JOB FOREIGN KEY (JOB_ID)\n    REFERENCES KONTRATA_JOBS (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_JOB_SKILLS_SKILL FOREIGN KEY (SKILL_ID)\n    REFERENCES KONTRATA_SKILLS (ID)\n);\n\nCOMMENT ON TABLE KONTRATA_JOB_SKILLS IS 'Habilidades essenciais de uma vaga, do catalogo KONTRATA_SKILLS';\n\nCREATE TABLE KONTRATA_JOB_STAGE (\n  JOB_ID   NUMBER NOT NULL,\n  STAGE_ID NUMBER NOT NULL,\n  POSITION NUMBER NOT NULL,\n  -- Email automatico por etapa da vaga. Spec:\n  -- docs/superpowers/specs/2026-08-27-email-automatico-etapas-vaga-design.md\n  --\n  -- STAGE_EMAIL_* mora em KONTRATA_JOB_STAGE porque a config e por VAGA, nao\n  -- pelo catalogo global de etapas: a mesma etapa do catalogo pode ter um\n  -- texto diferente em cada vaga que a usa. So as etapas do MIOLO do fluxo\n  -- recebem config hoje (as duas ancoras fixas nao tem nenhum campo editavel\n  -- por vaga, e isso nao muda aqui) — a coluna existe em toda linha da\n  -- tabela, mas so a camada de aplicacao decide quem a preenche.\n  STAGE_EMAIL_ENABLED NUMBER(1) DEFAULT 0 NOT NULL,\n  STAGE_EMAIL_SUBJECT VARCHAR2(200),\n  STAGE_EMAIL_BODY CLOB,\n  CONSTRAINT PK_KONTRATA_JOB_STAGE PRIMARY KEY (JOB_ID, POSITION),\n  CONSTRAINT FK_JOB_STAGE_JOB FOREIGN KEY (JOB_ID)\n    REFERENCES KONTRATA_JOBS (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_JOB_STAGE_STAGE FOREIGN KEY (STAGE_ID)\n    REFERENCES KONTRATA_STAGE (ID),\n  CONSTRAINT UQ_JOB_STAGE_STAGE UNIQUE (JOB_ID, STAGE_ID),\n  CONSTRAINT CK_JOB_STAGE_EMAIL_ENABLED CHECK (STAGE_EMAIL_ENABLED IN (0,1))\n);\n\nCREATE INDEX IX_JOB_STAGE_STAGE ON KONTRATA_JOB_STAGE (STAGE_ID);\n\nCOMMENT ON TABLE KONTRATA_JOB_STAGE IS 'Etapas do fluxo de uma vaga, ordenadas por POSITION';\n\nCOMMENT ON COLUMN KONTRATA_JOB_STAGE.STAGE_EMAIL_ENABLED IS '1 = envia e-mail automatico ao candidato quando a candidatura entra nesta etapa desta vaga';\nCOMMENT ON COLUMN KONTRATA_JOB_STAGE.STAGE_EMAIL_SUBJECT IS 'Assunto do e-mail, texto livre com variaveis {{candidato}}/{{vaga}}/{{etapa}}; NULL quando desabilitado';\nCOMMENT ON COLUMN KONTRATA_JOB_STAGE.STAGE_EMAIL_BODY IS 'Corpo do e-mail, texto livre com variaveis {{candidato}}/{{vaga}}/{{etapa}}; NULL quando desabilitado';\n\n-- Vínculo critério ↔ vaga. Substitui KONTRATA_JOB_PREREQUISITE e a config por\n-- vaga que vivia em KONTRATA_JOB_CRITERIA.\n--\n-- WEIGHT/BLOCKS_ADVANCE/AFFECTS_SCORE são copiados dos DEFAULT_* do catálogo no\n-- momento do vínculo — mudar o default depois não altera vaga já configurada.\n-- Os dois flags são ortogonais: BLOCKS_ADVANCE=1/AFFECTS_SCORE=0 é o critério\n-- só eliminatório (requisito binário é portão, não nota).\n--\n-- Spec: docs/superpowers/specs/2026-09-04-criterios-unificados-design.md\nCREATE TABLE KONTRATA_JOB_CRITERION (\n  JOB_ID          NUMBER NOT NULL,\n  CRITERION_ID    NUMBER NOT NULL,\n  POSITION        NUMBER NOT NULL,\n  WEIGHT          NUMBER(3) NOT NULL,\n  BLOCKS_ADVANCE  NUMBER(1) NOT NULL,\n  AFFECTS_SCORE   NUMBER(1) NOT NULL,\n  CONFIG_OVERRIDE CLOB CHECK (CONFIG_OVERRIDE IS JSON),\n  CONSTRAINT PK_JOB_CRITERION PRIMARY KEY (JOB_ID, CRITERION_ID),\n  CONSTRAINT FK_JOB_CRITERION_JOB FOREIGN KEY (JOB_ID)\n    REFERENCES KONTRATA_JOBS(ID) ON DELETE CASCADE,\n  CONSTRAINT FK_JOB_CRITERION_CRIT FOREIGN KEY (CRITERION_ID)\n    REFERENCES KONTRATA_CRITERION(ID),\n  CONSTRAINT UQ_JOB_CRITERION_POS UNIQUE (JOB_ID, POSITION),\n  CONSTRAINT CK_JOB_CRITERION_WEIGHT CHECK (WEIGHT BETWEEN 0 AND 100)\n);\n\nCREATE INDEX IX_JOB_CRITERION_CRIT ON KONTRATA_JOB_CRITERION (CRITERION_ID);\n\nCOMMENT ON TABLE KONTRATA_JOB_CRITERION IS 'Criterios de uma vaga, com peso e flags copiados do catalogo no vinculo';\nCOMMENT ON COLUMN KONTRATA_JOB_CRITERION.BLOCKS_ADVANCE IS 'Exige o dado: aparece nas pendencias do candidato e trava a etapa PREREQUISITES';\nCOMMENT ON COLUMN KONTRATA_JOB_CRITERION.AFFECTS_SCORE IS 'Resultado entra no matchScore';\nCOMMENT ON COLUMN KONTRATA_JOB_CRITERION.CONFIG_OVERRIDE IS 'Sobrescreve o CONFIG do catalogo nesta vaga; NULL = usa o do catalogo';\n\n-- Candidaturas: elo candidato-vaga, com etapa atual e desfecho. Ponteiro do\n-- estado atual — a HISTÓRIA de como chegou aqui mora em\n-- KONTRATA_APPLICATION_HISTORY (migration 0034), nunca aqui.\n\nCREATE TABLE KONTRATA_JOB_APPLICATIONS (\n  ID               NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  JOB_ID           NUMBER        NOT NULL,\n  CANDIDATE_ID     NUMBER        NOT NULL,\n  CURRENT_STAGE_ID NUMBER        NOT NULL,\n  OUTCOME          VARCHAR2(20),\n  CONSTRAINT PK_KONTRATA_JOB_APPLICATIONS PRIMARY KEY (ID),\n  CONSTRAINT FK_JOB_APPLICATIONS_JOB FOREIGN KEY (JOB_ID)\n    REFERENCES KONTRATA_JOBS (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_JOB_APPLICATIONS_CAND FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID),\n  CONSTRAINT UQ_JOB_APPLICATIONS UNIQUE (JOB_ID, CANDIDATE_ID),\n  CONSTRAINT FK_JOB_APPL_STAGE FOREIGN KEY (CURRENT_STAGE_ID)\n    REFERENCES KONTRATA_STAGE (ID),\n  CONSTRAINT CK_JOB_APPL_OUTCOME CHECK (OUTCOME IN ('HIRED', 'REJECTED', 'TRANSFERRED', 'WITHDRAWN'))\n);\n\nCREATE INDEX IDX_JOB_APPL_STAGE ON KONTRATA_JOB_APPLICATIONS (CURRENT_STAGE_ID);\nCREATE INDEX IDX_JOB_APPL_OUTCOME ON KONTRATA_JOB_APPLICATIONS (JOB_ID, OUTCOME);\n\nCOMMENT ON TABLE KONTRATA_JOB_APPLICATIONS IS 'Candidaturas: elo candidato-vaga, com etapa atual';\nCOMMENT ON COLUMN KONTRATA_JOB_APPLICATIONS.OUTCOME IS 'NULL = em andamento; preenchido = terminada, e CURRENT_STAGE_ID guarda onde parou';\n\nCREATE TABLE KONTRATA_STAGE_REQUIREMENT_DOCUMENT (\n  STAGE_REQUIREMENT_ID NUMBER NOT NULL,\n  DOCUMENT_TYPE        VARCHAR2(40) NOT NULL,\n  CONSTRAINT PK_STAGE_REQ_DOC PRIMARY KEY (STAGE_REQUIREMENT_ID, DOCUMENT_TYPE),\n  CONSTRAINT FK_STAGE_REQ_DOC_REQ FOREIGN KEY (STAGE_REQUIREMENT_ID)\n    REFERENCES KONTRATA_STAGE_REQUIREMENT (ID) ON DELETE CASCADE\n);\n\nCOMMENT ON TABLE KONTRATA_STAGE_REQUIREMENT_DOCUMENT IS 'Documentos do requisito: o que a coleta pede (SOLICITACAO_ANEXO/CADASTRO_ADMISSIONAL) ou o que a conferencia valida (VALIDACAO_ANEXOS)';\n\nCREATE TABLE KONTRATA_STAGE_FLOW_ITEM (\n  FLOW_ID  NUMBER NOT NULL,\n  STAGE_ID NUMBER NOT NULL,\n  POSITION NUMBER NOT NULL,\n  CONSTRAINT PK_STAGE_FLOW_ITEM PRIMARY KEY (FLOW_ID, POSITION),\n  CONSTRAINT FK_FLOW_ITEM_FLOW FOREIGN KEY (FLOW_ID)\n    REFERENCES KONTRATA_STAGE_FLOW (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_FLOW_ITEM_STAGE FOREIGN KEY (STAGE_ID)\n    REFERENCES KONTRATA_STAGE (ID),\n  CONSTRAINT UQ_FLOW_ITEM_STAGE UNIQUE (FLOW_ID, STAGE_ID)\n);\n\nCREATE INDEX IX_FLOW_ITEM_STAGE ON KONTRATA_STAGE_FLOW_ITEM (STAGE_ID);\n\nCOMMENT ON TABLE KONTRATA_STAGE_FLOW_ITEM IS 'Sequencia completa (ancoras + miolo) de um fluxo padrao, ordenada por POSITION';\n\n-- Vinculo 1:1 de cargo da Senior (por codigo) ao fluxo padrao que\n-- pre-preenche o fluxo de aprovacao da vaga daquele cargo.\n\nCREATE TABLE KONTRATA_STAGE_FLOW_CARGO (\n  SENIOR_CARGO_CODE VARCHAR2(30) NOT NULL,\n  FLOW_ID           NUMBER NOT NULL,\n  CREATED_BY        VARCHAR2(100) NOT NULL,\n  CREATED_AT        TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_STAGE_FLOW_CARGO PRIMARY KEY (SENIOR_CARGO_CODE),\n  CONSTRAINT FK_STAGE_FLOW_CARGO_FLOW FOREIGN KEY (FLOW_ID)\n    REFERENCES KONTRATA_STAGE_FLOW (ID)\n);\n\nCREATE INDEX IX_STAGE_FLOW_CARGO_FLOW ON KONTRATA_STAGE_FLOW_CARGO (FLOW_ID);\n\nCOMMENT ON TABLE KONTRATA_STAGE_FLOW_CARGO IS 'Vinculo 1:1 de cargo da Senior (por codigo) ao fluxo padrao que pre-preenche a vaga daquele cargo';\n\n-- Resposta crua de critério CATALOG_QUESTION com ANSWER_SCOPE='CANDIDATE':\n-- respondida uma vez, vale em toda vaga. Sujeita a VALIDITY_MONTHS do catálogo\n-- — vencida, volta a ser pendência.\n--\n-- Não guarda nota: a mesma resposta vale diferente em cada vaga (peso e\n-- CONFIG_OVERRIDE são por vínculo). A nota mora em\n-- KONTRATA_APPLICATION_CRITERION_RESULT, uma linha por candidatura.\n--\n-- Spec: docs/superpowers/specs/2026-09-04-criterios-unificados-design.md,\n-- docs/superpowers/specs/2026-09-11-pergunta-numerica-experiencia-design.md\n--\n-- OPTION_INDEX e NUMERIC_VALUE são mutuamente exclusivos: cada linha responde\n-- UMA pergunta, e o tipo dela (YES_NO/MULTIPLE_CHOICE vs. NUMERIC) decide qual\n-- coluna vale.\nCREATE TABLE KONTRATA_CANDIDATE_CRITERION_ANSWER (\n  CANDIDATE_ID  NUMBER NOT NULL,\n  CRITERION_ID  NUMBER NOT NULL,\n  OPTION_INDEX  NUMBER NULL,\n  NUMERIC_VALUE NUMBER NULL,\n  ANSWERED_AT   TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_CAND_CRIT_ANSWER PRIMARY KEY (CANDIDATE_ID, CRITERION_ID),\n  CONSTRAINT FK_CCA_CANDIDATE FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES(ID) ON DELETE CASCADE,\n  CONSTRAINT FK_CCA_CRITERION FOREIGN KEY (CRITERION_ID)\n    REFERENCES KONTRATA_CRITERION(ID),\n  CONSTRAINT CK_CCA_ANSWER_XOR\n    CHECK ((OPTION_INDEX IS NULL) <> (NUMERIC_VALUE IS NULL))\n);\n\nCREATE INDEX IX_CCA_CRITERION ON KONTRATA_CANDIDATE_CRITERION_ANSWER (CRITERION_ID);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_CRITERION_ANSWER IS 'Resposta reaproveitada entre vagas (ANSWER_SCOPE=CANDIDATE)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_CRITERION_ANSWER.OPTION_INDEX IS 'Indice na lista options do CONFIG do criterio';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_CRITERION_ANSWER.NUMERIC_VALUE IS 'Resposta de pergunta NUMERIC; mutuamente exclusivo com OPTION_INDEX';\n\n-- Dossie de admissao do candidato. FK = CANDIDATE_ID (nome correto p/\n-- KONTRATA_CANDIDATES), diferente das tabelas antigas que usam USER_ID.\n\nCREATE TABLE KONTRATA_CANDIDATE_DOCUMENTS (\n  ID             NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  CANDIDATE_ID   NUMBER NOT NULL,\n  APPLICATION_ID NUMBER,\n  DOCUMENT_TYPE  VARCHAR2(40) NOT NULL,\n  STATUS         VARCHAR2(20) NOT NULL,\n  DATA           CLOB,\n  AI_EXTRACTION  CLOB,\n  UPLOADED_AT    TIMESTAMP,\n  UPLOADED_BY    VARCHAR2(100),\n  VALIDATED_AT   TIMESTAMP,\n  VALIDATED_BY   VARCHAR2(100),\n  UPDATED_BY     VARCHAR2(100),\n  UPDATED_AT     TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CAND_DOCS PRIMARY KEY (ID),\n  CONSTRAINT FK_KONTRATA_CAND_DOCS_CAND FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_CAND_DOCS_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT CK_CAND_DOCS_STATUS CHECK (STATUS IN ('REQUESTED', 'SUBMITTED', 'VALID', 'INVALID'))\n);\n\n-- Unicidade CONDICIONAL: 1 registro por (candidato, candidatura, tipo), EXCETO\n-- DEPENDENTE e COMPROVANTE_ESCOLARIDADE (0..N). Nesses dois tipos as tres\n-- expressoes viram NULL; o Oracle nao indexa chave toda-nula, entao libera N\n-- linhas por candidato enquanto mantem unicidade para os demais tipos.\nCREATE UNIQUE INDEX UQ_CAND_DOCS_IDENTITY ON KONTRATA_CANDIDATE_DOCUMENTS (\n  CASE WHEN DOCUMENT_TYPE IN ('DEPENDENTE', 'COMPROVANTE_ESCOLARIDADE') THEN NULL ELSE CANDIDATE_ID END,\n  CASE WHEN DOCUMENT_TYPE IN ('DEPENDENTE', 'COMPROVANTE_ESCOLARIDADE') THEN NULL ELSE APPLICATION_ID END,\n  CASE WHEN DOCUMENT_TYPE IN ('DEPENDENTE', 'COMPROVANTE_ESCOLARIDADE') THEN NULL ELSE DOCUMENT_TYPE END\n);\n\nCREATE INDEX IX_KONTRATA_CAND_DOCS_CAND ON KONTRATA_CANDIDATE_DOCUMENTS (CANDIDATE_ID);\nCREATE INDEX IX_KONTRATA_CAND_DOCS_APP ON KONTRATA_CANDIDATE_DOCUMENTS (APPLICATION_ID);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_DOCUMENTS IS 'Documentos do candidato, um registro por (candidato, candidatura, tipo); update-in-place, nunca acumula versao';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_DOCUMENTS.DATA IS 'JSON dos campos crus extraidos do documento (OCR/LLM), em CLOB porque nenhum limite de tamanho cobre esse JSON';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_DOCUMENTS.AI_EXTRACTION IS 'JSON: {quality, checks, extraction} — leitura da IA sobre o documento atual';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_DOCUMENTS.STATUS IS 'Ciclo de vida do documento: REQUESTED ate ser enviado, depois SUBMITTED | VALID | INVALID';\n\nCREATE TABLE KONTRATA_CANDIDATE_DOCUMENT_FILES (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  DOCUMENT_ID NUMBER NOT NULL,\n  FILE_ID NUMBER NOT NULL,\n  FILE_NAME VARCHAR2(255),\n  MIME_TYPE VARCHAR2(120),\n  LABEL VARCHAR2(40),\n  UPLOADED_BY VARCHAR2(100) NOT NULL,\n  UPLOADED_BY_TYPE VARCHAR2(10) NOT NULL,\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_KONTRATA_CAND_DOC_FILES PRIMARY KEY (ID),\n  CONSTRAINT FK_KONTRATA_CAND_DOC_FILES_DOC FOREIGN KEY (DOCUMENT_ID)\n    REFERENCES KONTRATA_CANDIDATE_DOCUMENTS (ID) ON DELETE CASCADE,\n  CONSTRAINT CK_CAND_DOC_FILES_UPLOADER CHECK (UPLOADED_BY_TYPE IN ('RECRUITER', 'CANDIDATE'))\n);\n\nCREATE INDEX IX_KONTRATA_CAND_DOC_FILES_DOC ON KONTRATA_CANDIDATE_DOCUMENT_FILES (DOCUMENT_ID);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_DOCUMENT_FILES IS 'Arquivos anexados a um KONTRATA_CANDIDATE_DOCUMENTS (referencia ao storage-api)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_DOCUMENT_FILES.UPLOADED_BY IS 'Quem anexou: id do candidato (string) ou samAccountName do recrutador';\n\n-- Log apenas-inserção de eventos de documento (pedido/envio/reprovação).\n-- Substitui KONTRATA_DOCUMENT_REQUESTS, que só cobria\n-- \"pedido/reenvio\" e fingia histórico numa tabela à parte de\n-- KONTRATA_CANDIDATE_DOCUMENTS.\n--\n-- KONTRATA_CANDIDATE_DOCUMENTS continua existindo e sem mudança nenhuma: é o\n-- ponteiro (estado atual — leitura rápida de STATUS/DATA, e a base de\n-- KONTRATA_CANDIDATE_DOCUMENT_FILES, que também não muda). Esta tabela é só o\n-- rastro de COMO se chegou ali — mesmo par ponteiro+log já usado em\n-- KONTRATA_JOB_APPLICATIONS/KONTRATA_APPLICATION_HISTORY.\n--\n-- Tipos de coleção (DEPENDENTE, COMPROVANTE_ESCOLARIDADE, ASO_ADMISSIONAL)\n-- PASSAM por aqui como qualquer outro tipo: `createRequest`/`rejectDocument`\n-- não filtram singleton-vs-coleção, então os três podem receber REQUESTED/\n-- REJECTED normalmente. `createCollectionItem`/`updateCollectionItem`\n-- também gravam SUBMITTED nesta tabela (mesma transação do save no ponteiro\n-- KONTRATA_CANDIDATE_DOCUMENTS) — não só `upsertDocument`. Um pedido em\n-- aberto para um desses três tipos se resolve sozinho quando o candidato\n-- reenvia, igual a um tipo singleton.\n--\n-- ACTED_BY_TYPE = 'SYSTEM' cobre o REQUESTED disparado automaticamente ao\n-- entrar numa etapa que pede documento (ver `notifyMissingDocumentsForStage`,\n-- infra/documents/notify.ts) quando a transição em si não teve recrutador\n-- nenhum por trás — ex. o avanço automático que sai da etapa de\n-- pré-requisitos assim que o candidato termina de responder os critérios.\nCREATE TABLE KONTRATA_CANDIDATE_DOCUMENT_EVENT (\n  ID             NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  CANDIDATE_ID   NUMBER        NOT NULL,\n  APPLICATION_ID NUMBER,                    -- nulável: documento pode ser pedido fora de candidatura específica\n  DOCUMENT_TYPE  VARCHAR2(40)  NOT NULL,\n  EVENT_TYPE     VARCHAR2(10)  NOT NULL,\n  REASON         CLOB,                      -- motivo do REQUESTED/REJECTED, ou comentário interno do VALIDATED\n  DATA           CLOB,                      -- só em SUBMITTED: JSON dos campos no momento do envio\n  AI_EXTRACTION  CLOB,                      -- só em SUBMITTED: leitura da IA no momento do envio\n  ACTED_BY       VARCHAR2(100) NOT NULL,\n  ACTED_BY_TYPE  VARCHAR2(10)  NOT NULL,\n  ACTED_AT       TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_CAND_DOC_EVENT PRIMARY KEY (ID),\n  CONSTRAINT FK_CAND_DOC_EVENT_CAND FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_CAND_DOC_EVENT_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT CK_CAND_DOC_EVENT_TYPE\n    CHECK (EVENT_TYPE IN ('REQUESTED', 'SUBMITTED', 'VALIDATED', 'REJECTED')),\n  CONSTRAINT CK_CAND_DOC_EVENT_ACTOR CHECK (ACTED_BY_TYPE IN ('RECRUITER', 'CANDIDATE', 'SYSTEM'))\n);\nCREATE INDEX IX_CAND_DOC_EVENT_LOOKUP\n  ON KONTRATA_CANDIDATE_DOCUMENT_EVENT (CANDIDATE_ID, DOCUMENT_TYPE, APPLICATION_ID, ACTED_AT);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_DOCUMENT_EVENT IS\n  'Log apenas-inserção de pedido/envio/reprovação de documento (singleton e coleção) — companheiro de KONTRATA_CANDIDATE_DOCUMENTS, não substituto';\n\n-- Rastro da candidatura: o que aconteceu, quando, por quem. Tabela\n-- apenas-inserção — nunca UPDATE/MERGE sobre uma linha já gravada. Estado\n-- atual é sempre a última linha por chave; ver design em\n-- docs/superpowers/specs/2026-08-26-rastro-candidatura-eventos-design.md.\n\n-- Histórico de transições da candidatura\n-- (INSCRICAO/APPROVE/REJECT/RETURN/REOPEN).\n-- FROM_STAGE_ID anulável: NULL = inscrição ou reabertura, não veio de etapa\n-- nenhuma — mesmo idioma que TO_STAGE_ID já usa para \"destino é desfecho, não\n-- etapa\" (CK_APP_HIST_TERMINAL). REOPEN espelha isso ao contrário: a ORIGEM é\n-- o desfecho REJECTED (não uma etapa), então é FROM_STAGE_ID que fica NULL, e\n-- TO_STAGE_ID é obrigatório (a candidatura volta a ficar ativa numa etapa).\n-- Sem TO_OUTCOME: o desfecho de uma linha terminal (TO_STAGE_ID NULL) é\n-- sempre determinado por ACTION sozinho — REJECT só pode terminar em\n-- REJECTED, APPROVE terminal só pode terminar em HIRED — e é derivado na\n-- leitura (CASE ACTION WHEN 'REJECT' THEN 'REJECTED' ELSE 'HIRED' END), nunca\n-- gravado numa segunda coluna que só repetiria essa informação.\nCREATE TABLE KONTRATA_APPLICATION_HISTORY (\n  ID                     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  APPLICATION_ID         NUMBER        NOT NULL,\n  FROM_STAGE_ID          NUMBER,\n  TO_STAGE_ID            NUMBER,\n  ACTION                 VARCHAR2(10)  NOT NULL,\n  ACTED_BY               VARCHAR2(100) NOT NULL,\n  ACTED_BY_TYPE          VARCHAR2(10)  NOT NULL,\n  ACTED_AT               TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  NOTE                   CLOB,\n  RELATED_APPLICATION_ID NUMBER,\n  CONSTRAINT PK_APP_HISTORY PRIMARY KEY (ID),\n  CONSTRAINT FK_APP_HIST_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_APP_HIST_FROM FOREIGN KEY (FROM_STAGE_ID) REFERENCES KONTRATA_STAGE (ID),\n  CONSTRAINT FK_APP_HIST_TO FOREIGN KEY (TO_STAGE_ID) REFERENCES KONTRATA_STAGE (ID),\n  CONSTRAINT FK_APP_HIST_RELATED FOREIGN KEY (RELATED_APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT CK_APP_HIST_ACTION CHECK (ACTION IN ('INSCRICAO', 'APPROVE', 'REJECT', 'RETURN', 'REOPEN', 'TRANSFER', 'WITHDRAW')),\n  CONSTRAINT CK_APP_HIST_ACTOR_TYPE CHECK (ACTED_BY_TYPE IN ('RECRUITER', 'CANDIDATE', 'SYSTEM')),\n  CONSTRAINT CK_APP_HIST_TERMINAL CHECK (TO_STAGE_ID IS NOT NULL OR ACTION IN ('APPROVE', 'REJECT', 'TRANSFER', 'WITHDRAW'))\n);\n\nCREATE INDEX IX_APP_HIST_APP ON KONTRATA_APPLICATION_HISTORY (APPLICATION_ID, ACTED_AT);\n\n-- Garante no máximo uma linha INSCRICAO por candidatura — índice único\n-- funcional: Oracle não indexa chave NULL, então linhas com ACTION diferente\n-- de INSCRICAO produzem NULL e ficam de fora; duas linhas INSCRICAO para a\n-- mesma candidatura colidem e o segundo INSERT falha alto (ORA-00001), em vez\n-- de silenciosamente permitir a duplicata que quebraria a subquery escalar\n-- que `appliedAt` usa em toda leitura de candidatura.\nCREATE UNIQUE INDEX UX_APP_HIST_INSCRICAO ON KONTRATA_APPLICATION_HISTORY (\n  CASE WHEN ACTION = 'INSCRICAO' THEN APPLICATION_ID END\n);\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_HISTORY IS\n  'Histórico apenas-inserção de transições da candidatura (INSCRICAO/APPROVE/REJECT/RETURN/REOPEN)';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_HISTORY.FROM_STAGE_ID IS\n  'NULL = inscrição ou reabertura (não veio de etapa nenhuma). Preenchido = transição normal.';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_HISTORY.ACTED_BY IS\n  'Identificador do ator: samAccountName do AD (RECRUITER) ou CANDIDATE_ID como string (CANDIDATE) — ver ACTED_BY_TYPE.';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_HISTORY.ACTED_BY_TYPE IS\n  'Espaço de identidade de ACTED_BY: RECRUITER (AD) ou CANDIDATE (KONTRATA_CANDIDATES.ID).';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_HISTORY.RELATED_APPLICATION_ID IS\n  'Só em ACTION=TRANSFER: aponta pro outro lado da transferência (origem<->destino). ON DELETE CASCADE: apagar a candidatura referenciada (nunca acontece pela aplicação, só limpeza manual de dev/hml) apaga só ESTA linha de histórico — a candidatura dona dela, do outro lado da transferência, continua intacta.';\n\n-- Rastro da candidatura: o que aconteceu, quando, por quem. Tabela\n-- apenas-inserção — nunca UPDATE/MERGE sobre uma linha já gravada. Estado\n-- atual é sempre a última linha por chave; ver design em\n-- docs/superpowers/specs/2026-08-26-rastro-candidatura-eventos-design.md\n-- e docs/superpowers/specs/2026-09-18-remodelagem-eventos-requisito-design.md.\n\n-- Só 2 tipos gravam aqui: PARECER e INTEGRACAO_SENIOR —\n-- puro \"aconteceu, quando, por quem\" + nota livre opcional (só PARECER usa\n-- NOTE de fato). AGENDAMENTO_ENTREVISTA/AGENDAMENTO_EXAME têm tabela própria\n-- (KONTRATA_APPLICATION_SCHEDULING_EVENT, migration 0036) — precisam de\n-- colunas (horário, local, motivo de cancelamento) que os outros 2 tipos\n-- nunca usariam. ENVIO_PROPOSTA/ACEITE_PROPOSTA são calculados direto de\n-- KONTRATA_JOB_PROPOSALS, sem gravar aqui.\nCREATE TABLE KONTRATA_APPLICATION_REQUIREMENT_EVENT (\n  ID                   NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  APPLICATION_ID       NUMBER        NOT NULL,\n  STAGE_REQUIREMENT_ID NUMBER        NOT NULL,\n  FULFILLED            NUMBER(1)     NOT NULL,\n  -- Nota livre opcional — só PARECER preenche (o texto da avaliação). NULL\n  -- para INTEGRACAO_SENIOR (checkbox puro, sem conteúdo).\n  NOTE                 CLOB,\n  ACTED_BY             VARCHAR2(100) NOT NULL,\n  ACTED_BY_TYPE        VARCHAR2(10)  NOT NULL,\n  ACTED_AT             TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_APP_REQ_EVENT PRIMARY KEY (ID),\n  CONSTRAINT FK_APP_REQ_EVENT_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_APP_REQ_EVENT_REQ FOREIGN KEY (STAGE_REQUIREMENT_ID)\n    REFERENCES KONTRATA_STAGE_REQUIREMENT (ID),\n  CONSTRAINT CK_APP_REQ_EVENT_FULFILLED CHECK (FULFILLED IN (0, 1)),\n  CONSTRAINT CK_APP_REQ_EVENT_ACTOR CHECK (ACTED_BY_TYPE IN ('RECRUITER', 'CANDIDATE', 'SYSTEM'))\n);\n\nCREATE INDEX IX_APP_REQ_EVENT_LOOKUP\n  ON KONTRATA_APPLICATION_REQUIREMENT_EVENT (APPLICATION_ID, STAGE_REQUIREMENT_ID, ACTED_AT);\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_REQUIREMENT_EVENT IS\n  'Log apenas-inserção de cumprimento de requisito (PARECER/INTEGRACAO_SENIOR); estado atual = última linha por (APPLICATION_ID, STAGE_REQUIREMENT_ID)';\n\nCOMMENT ON COLUMN KONTRATA_APPLICATION_REQUIREMENT_EVENT.NOTE IS\n  'Nota livre opcional; só PARECER preenche. NULL para os outros 2 tipos.';\n\n-- Sem ON DELETE CASCADE no FK acima DE PROPOSITO: updateStage faz\n-- DELETE+INSERT em KONTRATA_STAGE_REQUIREMENT a cada save. Sem cascade, o\n-- DELETE falha alto (ORA-02292) se houver dependente — e essa falha e'\n-- interceptada em pipeline-catalog/service.ts com uma mensagem legivel antes\n-- de chegar aqui.\n\n-- Agendamento de entrevista OU exame: tabela dedicada, separada da tabela\n-- genérica de requisito (KONTRATA_APPLICATION_REQUIREMENT_EVENT, migration\n-- 0035) — os dois precisam de intervalo de tempo (ou instante único, no\n-- caso do exame) e de consulta cross-candidatura, nenhum outro tipo de\n-- requisito precisa de nenhuma das duas. Ver design em\n-- docs/superpowers/specs/2026-09-18-remodelagem-eventos-requisito-design.md\n-- (fundiu duas tabelas antes separadas — AGENDAMENTO_EXAME morava, mal, na\n-- tabela genérica).\n--\n-- Apenas-inserção, mesmo padrão do resto do rastro: cada agendamento/\n-- reagendamento é uma linha nova, nunca sobrescreve a anterior. Estado atual\n-- = última linha por (APPLICATION_ID, STAGE_REQUIREMENT_ID), ordenando por\n-- ACTED_AT DESC, ID DESC. Sem FULFILLED/ACTED_BY_TYPE: toda linha aqui É um\n-- agendamento (a existência da linha = \"cumprido\"), e só recrutador agenda —\n-- não existe caminho do candidato até esta tabela.\nCREATE TABLE KONTRATA_APPLICATION_SCHEDULING_EVENT (\n  ID                   NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  APPLICATION_ID       NUMBER        NOT NULL,\n  STAGE_REQUIREMENT_ID NUMBER        NOT NULL,\n  CANDIDATE_ID         NUMBER        NOT NULL,\n  START_AT             TIMESTAMP     NOT NULL,\n  -- NULL para AGENDAMENTO_EXAME (só um instante, sem duração/checagem de\n  -- conflito). Obrigatório em código (não em CHECK) para AGENDAMENTO_ENTREVISTA.\n  END_AT               TIMESTAMP,\n  INSTRUCTIONS         VARCHAR2(500),\n  --\n  CLINIC_SENIOR_CODE   NUMBER,\n  CLINIC_NAME          VARCHAR2(255),\n  CLINIC_ZIP           VARCHAR2(8),\n  CLINIC_STREET_TYPE   VARCHAR2(4),\n  CLINIC_STREET        VARCHAR2(255),\n  CLINIC_NUMBER        VARCHAR2(20),\n  CLINIC_COMPLEMENT    VARCHAR2(100),\n  CLINIC_DISTRICT      VARCHAR2(120),\n  CLINIC_CITY_IBGE     NUMBER,\n  CLINIC_CITY_NAME     VARCHAR2(120),\n  CLINIC_STATE         VARCHAR2(2),\n  -- Texto exibido no bloco da grade semanal — só AGENDAMENTO_ENTREVISTA usa\n  -- (exame não participa da grade compartilhada, renderiza bloco próprio).\n  -- NULL = front usa o padrão calculado na hora (candidato — etapa — vaga).\n  CALENDAR_TITLE       VARCHAR2(200),\n  -- Anotação livre do recrutador pra lembrar depois — só AGENDAMENTO_ENTREVISTA.\n  CALENDAR_DESCRIPTION VARCHAR2(2000),\n  ACTED_BY             VARCHAR2(100) NOT NULL,\n  ACTED_AT             TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  -- SCHEDULED = agendamento; CANCELED = cancelamento (copia\n  -- START_AT/END_AT/INSTRUCTIONS/CANDIDATE_ID da linha sendo cancelada). Estado\n  -- atual = última linha por (APPLICATION_ID, STAGE_REQUIREMENT_ID) — só\n  -- conta como agendado se EVENT_TYPE = SCHEDULED.\n  EVENT_TYPE           VARCHAR2(10)  DEFAULT 'SCHEDULED' NOT NULL,\n  -- Motivo do cancelamento — obrigatório na aplicação para linhas CANCELED,\n  -- sempre NULL em linhas SCHEDULED. Coluna própria: INSTRUCTIONS nunca mais\n  -- carrega o motivo (bug que existia pro exame antes desta migration).\n  REASON               CLOB,\n  -- E-mail — auditoria do texto FINAL (tokens já substituídos) enviado ao\n  -- candidato neste agendamento OU cancelamento. NULL quando o recrutador\n  -- não preencheu um e-mail (opcional nos dois casos, não só em CANCELED).\n  EMAIL_SUBJECT        VARCHAR2(200),\n  EMAIL_BODY           CLOB,\n  CONSTRAINT PK_APP_SCHEDULING_EVENT PRIMARY KEY (ID),\n  CONSTRAINT FK_APP_SCHEDULING_EVENT_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_APP_SCHEDULING_EVENT_REQ FOREIGN KEY (STAGE_REQUIREMENT_ID)\n    REFERENCES KONTRATA_STAGE_REQUIREMENT (ID),\n  CONSTRAINT FK_APP_SCHEDULING_EVENT_CAND FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID),\n  CONSTRAINT CK_APP_SCHEDULING_EVENT_RANGE CHECK (END_AT IS NULL OR END_AT > START_AT),\n  CONSTRAINT CK_APP_SCHEDULING_EVENT_TYPE CHECK (EVENT_TYPE IN ('SCHEDULED', 'CANCELED'))\n);\n\nCREATE INDEX IX_APP_SCHEDULING_EVENT_LOOKUP\n  ON KONTRATA_APPLICATION_SCHEDULING_EVENT (APPLICATION_ID, STAGE_REQUIREMENT_ID, ACTED_AT);\nCREATE INDEX IX_APP_SCHEDULING_EVENT_RECRUITER\n  ON KONTRATA_APPLICATION_SCHEDULING_EVENT (ACTED_BY, START_AT);\nCREATE INDEX IX_APP_SCHEDULING_EVENT_CANDIDATE\n  ON KONTRATA_APPLICATION_SCHEDULING_EVENT (CANDIDATE_ID, START_AT);\n-- \"Quantos candidatos já têm horário nesta clínica\" (exame, contagem\n-- informativa, não bloqueia).\nCREATE INDEX IX_APP_SCHEDULING_EVENT_CLINIC\n  ON KONTRATA_APPLICATION_SCHEDULING_EVENT (CLINIC_SENIOR_CODE, CLINIC_ZIP, CLINIC_NUMBER, START_AT);\n\n-- Sem ON DELETE CASCADE no FK de STAGE_REQUIREMENT_ID, mesmo motivo da\n-- migration 0035: updateStage faz DELETE+INSERT em KONTRATA_STAGE_REQUIREMENT\n-- a cada save. Sem cascade, editar uma etapa com agendamentos já marcados\n-- falha alto (ORA-02292) — interceptado com mensagem legível em\n-- pipeline-catalog/service.ts#assertNoApplicationProgress.\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_SCHEDULING_EVENT IS\n  'Log apenas-inserção de agendamento/reagendamento (AGENDAMENTO_ENTREVISTA e AGENDAMENTO_EXAME) — tabela dedicada, separada de KONTRATA_APPLICATION_REQUIREMENT_EVENT.';\n\nCOMMENT ON COLUMN KONTRATA_APPLICATION_SCHEDULING_EVENT.END_AT IS\n  'NULL para AGENDAMENTO_EXAME (instante único, sem checagem de conflito). Obrigatório em código para AGENDAMENTO_ENTREVISTA.';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_SCHEDULING_EVENT.CALENDAR_TITLE IS\n  'So AGENDAMENTO_ENTREVISTA usa; NULL = front usa o padrao calculado (candidato - etapa - vaga).';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_SCHEDULING_EVENT.CALENDAR_DESCRIPTION IS\n  'So AGENDAMENTO_ENTREVISTA usa, exibida na ficha do compromisso.';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_SCHEDULING_EVENT.EVENT_TYPE IS\n  'SCHEDULED = agendamento; CANCELED = cancelamento. Estado atual = ultima linha por (APPLICATION_ID, STAGE_REQUIREMENT_ID) - so conta como agendado se EVENT_TYPE = SCHEDULED.';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_SCHEDULING_EVENT.REASON IS\n  'Motivo do cancelamento - obrigatorio na aplicacao para linhas CANCELED, sempre NULL em linhas SCHEDULED.';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_SCHEDULING_EVENT.EMAIL_SUBJECT IS\n  'Assunto final (tokens ja substituidos) do e-mail enviado ao candidato neste agendamento ou cancelamento; NULL se o recrutador nao preencheu um e-mail';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_SCHEDULING_EVENT.EMAIL_BODY IS\n  'Corpo final (tokens ja substituidos, texto puro) do e-mail enviado ao candidato neste agendamento ou cancelamento; NULL se o recrutador nao preencheu um e-mail';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_SCHEDULING_EVENT.INSTRUCTIONS IS\n  'Instrucoes ao candidato (sala, link, jejum, documento). Antes se chamava LOCATION.';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_SCHEDULING_EVENT.CLINIC_SENIOR_CODE IS\n  'R110POS.CODPOS (posto de atendimento) da clinica do exame; NULL = endereco digitado a mao. Colunas CLINIC_* so no AGENDAMENTO_EXAME.';\n\n-- Resposta crua de critério CATALOG_QUESTION com ANSWER_SCOPE='APPLICATION':\n-- pertence àquela candidatura e é pedida de novo em cada nova candidatura,\n-- porque a resposta é sobre a vaga (\"aceita escala 6x1 nesta loja?\"), não sobre\n-- o candidato.\n--\n-- Spec: docs/superpowers/specs/2026-09-04-criterios-unificados-design.md,\n-- docs/superpowers/specs/2026-09-11-pergunta-numerica-experiencia-design.md\n--\n-- OPTION_INDEX e NUMERIC_VALUE são mutuamente exclusivos: cada linha responde\n-- UMA pergunta, e o tipo dela (YES_NO/MULTIPLE_CHOICE vs. NUMERIC) decide qual\n-- coluna vale.\nCREATE TABLE KONTRATA_APPLICATION_CRITERION_ANSWER (\n  APPLICATION_ID NUMBER NOT NULL,\n  CRITERION_ID   NUMBER NOT NULL,\n  OPTION_INDEX   NUMBER NULL,\n  NUMERIC_VALUE  NUMBER NULL,\n  ANSWERED_AT    TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_APP_CRIT_ANSWER PRIMARY KEY (APPLICATION_ID, CRITERION_ID),\n  CONSTRAINT FK_ACA_APPLICATION FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS(ID) ON DELETE CASCADE,\n  CONSTRAINT FK_ACA_CRITERION FOREIGN KEY (CRITERION_ID)\n    REFERENCES KONTRATA_CRITERION(ID),\n  CONSTRAINT CK_ACA_ANSWER_XOR\n    CHECK ((OPTION_INDEX IS NULL) <> (NUMERIC_VALUE IS NULL))\n);\n\nCREATE INDEX IX_ACA_CRITERION ON KONTRATA_APPLICATION_CRITERION_ANSWER (CRITERION_ID);\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_CRITERION_ANSWER IS 'Resposta one-shot da candidatura (ANSWER_SCOPE=APPLICATION)';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_CRITERION_ANSWER.NUMERIC_VALUE IS 'Resposta de pergunta NUMERIC; mutuamente exclusivo com OPTION_INDEX';\n\n-- Resultado avaliado: UMA linha por critério da vaga, por candidatura,\n-- independente do VALUE_MODE. É a única tabela lida para calcular o matchScore:\n--\n--   SELECT SUM(SCORE * WEIGHT) / SUM(WEIGHT) ... WHERE AFFECTS_SCORE = 1\n--\n-- Existe porque PROFILE_FIELD e INSTRUMENT não têm linha de resposta em lugar\n-- nenhum (o valor vem do perfil ou do subsistema), e porque a mesma resposta de\n-- escopo candidato vale diferente em cada vaga.\n--\n-- WEIGHT e AFFECTS_SCORE são congelados aqui: recalibrar a vaga depois não muda\n-- a nota de candidatura já avaliada.\n--\n-- Spec: docs/superpowers/specs/2026-09-04-criterios-unificados-design.md\nCREATE TABLE KONTRATA_APPLICATION_CRITERION_RESULT (\n  APPLICATION_ID NUMBER NOT NULL,\n  CRITERION_ID   NUMBER NOT NULL,\n  SCORE          NUMBER(3),\n  WEIGHT         NUMBER(3) NOT NULL,\n  AFFECTS_SCORE  NUMBER(1) NOT NULL,\n  ELIMINATED     NUMBER(1) DEFAULT 0 NOT NULL,\n  EVALUATED_AT   TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_APP_CRIT_RESULT PRIMARY KEY (APPLICATION_ID, CRITERION_ID),\n  CONSTRAINT FK_ACR_APPLICATION FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS(ID) ON DELETE CASCADE,\n  CONSTRAINT FK_ACR_CRITERION FOREIGN KEY (CRITERION_ID)\n    REFERENCES KONTRATA_CRITERION(ID),\n  CONSTRAINT CK_ACR_SCORE CHECK (SCORE IS NULL OR SCORE BETWEEN 0 AND 100)\n);\n\nCREATE INDEX IX_ACR_CRITERION ON KONTRATA_APPLICATION_CRITERION_RESULT (CRITERION_ID);\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_CRITERION_RESULT IS 'Nota apurada por criterio da vaga, por candidatura — base do matchScore';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_CRITERION_RESULT.SCORE IS '0-100; NULL quando nao ha valor apurado (instrumento que nao rodou, ou dado ausente). Portao puro (AFFECTS_SCORE=0) tambem grava nota — ela so fica fora da media';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_CRITERION_RESULT.WEIGHT IS 'Peso vigente na avaliacao — congelado para auditoria';\n\nCREATE TABLE KONTRATA_CANDIDATE_PROFILE_ANALYSIS (\n  APPLICATION_ID          NUMBER        NOT NULL,\n  MATCH_SCORE             NUMBER(3),\n  CURRICULUM_MATCH_RESULT CLOB          NOT NULL,\n  MODEL                   VARCHAR2(100) NOT NULL,\n  GENERATED_AT            TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_CANDIDATE_PROFILE_ANALYSIS PRIMARY KEY (APPLICATION_ID),\n  CONSTRAINT FK_CANDIDATE_PROFILE_ANALYSIS_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE\n);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_PROFILE_ANALYSIS IS 'Cache da analise de perfil do candidato (IA + criterios), advisory';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_PROFILE_ANALYSIS.MATCH_SCORE IS '0-100; NULL quando nao ha nota (eliminado, ou nenhum criterio pontua)';\n\n-- Rastro de reavaliação: por que a nota de um critério mudou, quando, e o que\n-- disparou. Tabela apenas-inserção — nunca UPDATE/MERGE. O estado ATUAL vive em\n-- KONTRATA_APPLICATION_CRITERION_RESULT (uma linha por critério, sobrescrita);\n-- esta guarda o que aquela apaga.\n--\n-- Não existe SCORE_AFTER de propósito: o valor \"depois\" é o SCORE_BEFORE do\n-- evento seguinte DO MESMO CRITÉRIO ou, no evento mais recente, o SCORE atual em\n-- ..._CRITERION_RESULT. Só o SCORE_BEFORE é irrecuperável. Quem reconstruir a\n-- série tem de particionar a janela por (APPLICATION_ID, CRITERION_ID): uma\n-- reavaliação pode gravar dois eventos no mesmo instante, e um LEAD por\n-- candidatura pegaria o critério errado.\nCREATE TABLE KONTRATA_APPLICATION_REEVALUATION_EVENT (\n  ID              NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  APPLICATION_ID  NUMBER        NOT NULL,\n  CRITERION_ID    NUMBER        NOT NULL,\n  SCORE_BEFORE    NUMBER(3),\n  ELIMINATED_NOW  NUMBER(1)     NOT NULL,\n  TRIGGER_FIELD   VARCHAR2(30)  NOT NULL,\n  ACTED_BY        VARCHAR2(100) NOT NULL,\n  ACTED_BY_TYPE   VARCHAR2(10)  NOT NULL,\n  ACTED_AT        TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_APP_REEVAL_EVENT PRIMARY KEY (ID),\n  CONSTRAINT FK_APP_REEVAL_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_APP_REEVAL_CRIT FOREIGN KEY (CRITERION_ID)\n    REFERENCES KONTRATA_CRITERION (ID),\n  CONSTRAINT CK_APP_REEVAL_ELIM CHECK (ELIMINATED_NOW IN (0, 1)),\n  CONSTRAINT CK_APP_REEVAL_ACTOR CHECK (ACTED_BY_TYPE IN ('RECRUITER', 'CANDIDATE', 'SYSTEM')),\n  CONSTRAINT CK_APP_REEVAL_SCORE_BEFORE CHECK (SCORE_BEFORE IS NULL OR SCORE_BEFORE BETWEEN 0 AND 100)\n);\n\nCREATE INDEX IX_APP_REEVAL_APP\n  ON KONTRATA_APPLICATION_REEVALUATION_EVENT (APPLICATION_ID, ACTED_AT);\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_REEVALUATION_EVENT IS 'Rastro de mudanca de nota por reavaliacao (edicao de perfil do candidato)';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_REEVALUATION_EVENT.TRIGGER_FIELD IS 'Campo do perfil que disparou: AGE | HAS_DRIVERS_LICENSE | HAS_OWN_VEHICLE | COMMUTE_DISTANCE | EXPERIENCE_YEARS. So EXPERIENCE_YEARS muda o insumo da IA e vai pela fila de analise completa; os demais pela fila barata de criterio. Linhas antigas podem ter SALARY_EXPECTATION (PROFILE_FIELD aposentado em 2026-09-14, virou CATALOG_QUESTION/APPLICATION) ou CURRICULUM_FILE (gatilho removido: o upload do arquivo nao muda o que a IA le). Analise que nao veio de edicao de perfil (primeira avaliacao da candidatura, botao do recrutador) nao gera linha aqui';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_REEVALUATION_EVENT.SCORE_BEFORE IS 'Nota antes desta reavaliacao; a nota depois e derivada (ver comentario do CREATE TABLE)';\n\n-- Categoria do banco de questões de prova (ex: \"Excel\", \"Lógica\"). CRUD do\n-- recrutador — spec própria de autoria decide o endpoint.\n--\n-- Spec: docs/superpowers/specs/2026-09-11-banco-de-provas-design.md\nCREATE TABLE KONTRATA_EXAM_CATEGORY (\n  ID         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  LABEL      VARCHAR2(200) NOT NULL,\n  CREATED_BY VARCHAR2(100) NOT NULL,\n  CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_BY VARCHAR2(100),\n  UPDATED_AT TIMESTAMP,\n  DELETED_BY VARCHAR2(100),\n  DELETED_AT TIMESTAMP,\n  CONSTRAINT PK_EXAM_CATEGORY PRIMARY KEY (ID)\n);\n\n-- Unicidade só entre categorias vivas: excluir uma (soft-delete) não pode\n-- queimar o rótulo pra sempre — mesmo padrão de UQ_SKILL_GROUPS_NAME (0004) e\n-- UQ_SKILLS_NAME (0018).\nCREATE UNIQUE INDEX UQ_EXAM_CATEGORY_LABEL\n  ON KONTRATA_EXAM_CATEGORY (CASE WHEN DELETED_AT IS NULL THEN UPPER(LABEL) END);\n\nCOMMENT ON TABLE KONTRATA_EXAM_CATEGORY IS 'Categoria do banco de questoes de prova, gerida pelo recrutador';\n\n-- Questão reutilizável do banco de provas. OPTIONS carrega o gabarito\n-- (isCorrect por opção) — nunca exposto ao candidato antes de responder.\n--\n-- Spec: docs/superpowers/specs/2026-09-11-banco-de-provas-design.md\nCREATE TABLE KONTRATA_EXAM_QUESTION (\n  ID            NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  CATEGORY_ID   NUMBER NOT NULL,\n  STATEMENT     VARCHAR2(2000) NOT NULL,\n  QUESTION_TYPE VARCHAR2(20) NOT NULL,\n  OPTIONS       CLOB NOT NULL CHECK (OPTIONS IS JSON),\n  WEIGHT        NUMBER(3) DEFAULT 1 NOT NULL,\n  CREATED_BY    VARCHAR2(100) NOT NULL,\n  CREATED_AT    TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_BY    VARCHAR2(100),\n  UPDATED_AT    TIMESTAMP,\n  DELETED_BY    VARCHAR2(100),\n  DELETED_AT    TIMESTAMP,\n  CONSTRAINT PK_EXAM_QUESTION PRIMARY KEY (ID),\n  CONSTRAINT FK_EXAM_QUESTION_CATEGORY FOREIGN KEY (CATEGORY_ID)\n    REFERENCES KONTRATA_EXAM_CATEGORY(ID),\n  CONSTRAINT CK_EXAM_QUESTION_TYPE CHECK (QUESTION_TYPE IN ('SINGLE_CHOICE','MULTIPLE_CHOICE','TRUE_FALSE')),\n  CONSTRAINT CK_EXAM_QUESTION_WEIGHT CHECK (WEIGHT > 0)\n);\n\nCREATE INDEX IX_EXAM_QUESTION_CATEGORY ON KONTRATA_EXAM_QUESTION (CATEGORY_ID);\n\nCOMMENT ON TABLE KONTRATA_EXAM_QUESTION IS 'Questao reutilizavel do banco de provas';\nCOMMENT ON COLUMN KONTRATA_EXAM_QUESTION.QUESTION_TYPE IS 'SINGLE_CHOICE | MULTIPLE_CHOICE | TRUE_FALSE';\nCOMMENT ON COLUMN KONTRATA_EXAM_QUESTION.OPTIONS IS 'JSON: [{label, isCorrect}] — gabarito, nunca exposto ao candidato';\nCOMMENT ON COLUMN KONTRATA_EXAM_QUESTION.WEIGHT IS 'Peso da questao na nota da prova (soma dos pesos das questoes vinculadas)';\n\n-- Prova: agrupa questões do banco. Nasce em DRAFT sem CRITERION_ID; ao\n-- publicar, ganha 1 linha em KONTRATA_CRITERION (instrument=EXAM) e vira\n-- PUBLISHED — só a partir daí é vinculável a uma vaga.\n--\n-- ELIMINATES_BELOW_PASSING_SCORE aqui é só o PADRÃO do catálogo: cada vaga\n-- pode sobrescrever via CONFIG_OVERRIDE em KONTRATA_JOB_CRITERION.\n--\n-- Spec: docs/superpowers/specs/2026-09-11-banco-de-provas-design.md\nCREATE TABLE KONTRATA_EXAM (\n  ID                             NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  TITLE                          VARCHAR2(400) NOT NULL,\n  DESCRIPTION                    VARCHAR2(2000),\n  INSTRUCTIONS                   VARCHAR2(2000),\n  PASSING_SCORE                  NUMBER(3) NOT NULL,\n  TIME_LIMIT_MINUTES             NUMBER(4) NOT NULL,\n  ELIMINATES_BELOW_PASSING_SCORE NUMBER(1) DEFAULT 0 NOT NULL,\n  STATUS                         VARCHAR2(20) DEFAULT 'DRAFT' NOT NULL,\n  CRITERION_ID                   NUMBER,\n  CREATED_BY                     VARCHAR2(100) NOT NULL,\n  CREATED_AT                     TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_BY                     VARCHAR2(100),\n  UPDATED_AT                     TIMESTAMP,\n  DELETED_BY                     VARCHAR2(100),\n  DELETED_AT                     TIMESTAMP,\n  CONSTRAINT PK_EXAM PRIMARY KEY (ID),\n  CONSTRAINT FK_EXAM_CRITERION FOREIGN KEY (CRITERION_ID)\n    REFERENCES KONTRATA_CRITERION(ID),\n  CONSTRAINT UQ_EXAM_CRITERION UNIQUE (CRITERION_ID),\n  CONSTRAINT CK_EXAM_STATUS CHECK (STATUS IN ('DRAFT','PUBLISHED')),\n  CONSTRAINT CK_EXAM_PASSING_SCORE CHECK (PASSING_SCORE BETWEEN 0 AND 100),\n  CONSTRAINT CK_EXAM_TIME_LIMIT CHECK (TIME_LIMIT_MINUTES > 0),\n  CONSTRAINT CK_EXAM_ELIMINATES CHECK (ELIMINATES_BELOW_PASSING_SCORE IN (0, 1)),\n  CONSTRAINT CK_EXAM_CRITERION_ON_PUBLISH CHECK (STATUS = 'DRAFT' OR CRITERION_ID IS NOT NULL)\n);\n\nCOMMENT ON TABLE KONTRATA_EXAM IS 'Prova: agrupa questoes do banco. Publicada = tem CRITERION_ID e aparece no catalogo de criterios';\nCOMMENT ON COLUMN KONTRATA_EXAM.DESCRIPTION IS 'Proposito da prova, exibido ao candidato antes de comecar; opcional';\nCOMMENT ON COLUMN KONTRATA_EXAM.INSTRUCTIONS IS 'Instrucoes/recomendacoes exibidas ao candidato antes de comecar; opcional';\nCOMMENT ON COLUMN KONTRATA_EXAM.CRITERION_ID IS 'Espelho para KONTRATA_CRITERION (instrument=EXAM); NULL enquanto DRAFT';\nCOMMENT ON COLUMN KONTRATA_EXAM.ELIMINATES_BELOW_PASSING_SCORE IS 'Padrao do catalogo; vaga pode sobrescrever via KONTRATA_JOB_CRITERION.CONFIG_OVERRIDE';\n\n-- Quais questões compõem uma prova, e em que ordem de autoria (a ordem\n-- REAL exibida ao candidato é sorteada por tentativa — ver\n-- KONTRATA_APPLICATION_EXAM_ANSWER.PRESENTED_POSITION).\n--\n-- Spec: docs/superpowers/specs/2026-09-11-banco-de-provas-design.md\nCREATE TABLE KONTRATA_EXAM_QUESTION_LINK (\n  EXAM_ID     NUMBER NOT NULL,\n  QUESTION_ID NUMBER NOT NULL,\n  POSITION    NUMBER NOT NULL,\n  WEIGHT      NUMBER(3),\n  CONSTRAINT PK_EXAM_QUESTION_LINK PRIMARY KEY (EXAM_ID, QUESTION_ID),\n  CONSTRAINT FK_EQL_EXAM FOREIGN KEY (EXAM_ID)\n    REFERENCES KONTRATA_EXAM(ID) ON DELETE CASCADE,\n  CONSTRAINT FK_EQL_QUESTION FOREIGN KEY (QUESTION_ID)\n    REFERENCES KONTRATA_EXAM_QUESTION(ID),\n  CONSTRAINT UQ_EQL_POSITION UNIQUE (EXAM_ID, POSITION),\n  CONSTRAINT CK_EQL_WEIGHT CHECK (WEIGHT IS NULL OR WEIGHT > 0)\n);\n\nCREATE INDEX IX_EQL_QUESTION ON KONTRATA_EXAM_QUESTION_LINK (QUESTION_ID);\n\nCOMMENT ON TABLE KONTRATA_EXAM_QUESTION_LINK IS 'Questoes que compoem uma prova, na ordem de autoria';\nCOMMENT ON COLUMN KONTRATA_EXAM_QUESTION_LINK.WEIGHT IS 'Override do peso da questao so nesta prova; NULL usa o peso padrao de KONTRATA_EXAM_QUESTION.WEIGHT';\n\n-- Tentativa da prova nesta candidatura — no máximo 1 por (APPLICATION_ID,\n-- EXAM_ID). SCORE é a nota final (0-100), gravada no envio (explícito ou\n-- auto-submit por prazo esgotado); SUBMITTED_AT nulo = ainda em andamento ou\n-- nem iniciada. NUMBER(5,2): a fórmula (100 * peso correto / peso total) é\n-- fracionária para quase qualquer conjunto de questões, e arredondar para\n-- inteiro (NUMBER(3)) podia empurrar uma nota pra cima do PASSING_SCORE.\n--\n-- Sem coluna ELIMINATED: ao contrário do sketch original da spec, quem decide\n-- eliminação é sempre KONTRATA_APPLICATION_CRITERION_RESULT.ELIMINATED — fonte\n-- única para todo tipo de critério. Duplicar aqui criaria uma segunda cópia\n-- que podia divergir da primeira.\n--\n-- Spec: docs/superpowers/specs/2026-09-11-banco-de-provas-design.md\nCREATE TABLE KONTRATA_APPLICATION_EXAM (\n  ID               NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  APPLICATION_ID   NUMBER NOT NULL,\n  EXAM_ID          NUMBER NOT NULL,\n  STARTED_AT       TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  SUBMITTED_AT     TIMESTAMP,\n  SCORE            NUMBER(5,2),\n  FOCUS_LOST_COUNT NUMBER(4) DEFAULT 0 NOT NULL,\n  CONSTRAINT PK_APPLICATION_EXAM PRIMARY KEY (ID),\n  CONSTRAINT FK_APP_EXAM_APPLICATION FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS(ID) ON DELETE CASCADE,\n  CONSTRAINT FK_APP_EXAM_EXAM FOREIGN KEY (EXAM_ID)\n    REFERENCES KONTRATA_EXAM(ID),\n  CONSTRAINT UQ_APP_EXAM UNIQUE (APPLICATION_ID, EXAM_ID),\n  CONSTRAINT CK_APP_EXAM_SCORE CHECK (SCORE IS NULL OR SCORE BETWEEN 0 AND 100)\n);\n\nCREATE INDEX IX_APP_EXAM_EXAM ON KONTRATA_APPLICATION_EXAM (EXAM_ID);\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_EXAM IS 'Tentativa unica da prova nesta candidatura';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_EXAM.SCORE IS '0-100; nulo enquanto nao enviada (SUBMITTED_AT nulo)';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_EXAM.FOCUS_LOST_COUNT IS 'Quantas vezes a aba/janela perdeu foco durante a prova — sinal para o recrutador, nao bloqueia';\n\n-- Resposta de UMA questão dentro de uma tentativa. PRESENTED_POSITION e\n-- PRESENTED_OPTION_ORDER gravam a ordem SORTEADA que o candidato viu —\n-- sem isso não dá para reconstruir a tela na revisão do recrutador.\n--\n-- Spec: docs/superpowers/specs/2026-09-11-banco-de-provas-design.md\nCREATE TABLE KONTRATA_APPLICATION_EXAM_ANSWER (\n  APPLICATION_EXAM_ID    NUMBER NOT NULL,\n  QUESTION_ID            NUMBER NOT NULL,\n  PRESENTED_POSITION     NUMBER NOT NULL,\n  PRESENTED_OPTION_ORDER CLOB NOT NULL CHECK (PRESENTED_OPTION_ORDER IS JSON),\n  SELECTED_OPTIONS       CLOB CHECK (SELECTED_OPTIONS IS JSON),\n  IS_CORRECT             NUMBER(1),\n  ANSWERED_AT            TIMESTAMP,\n  CONSTRAINT PK_APP_EXAM_ANSWER PRIMARY KEY (APPLICATION_EXAM_ID, QUESTION_ID),\n  CONSTRAINT FK_AEA_APP_EXAM FOREIGN KEY (APPLICATION_EXAM_ID)\n    REFERENCES KONTRATA_APPLICATION_EXAM(ID) ON DELETE CASCADE,\n  CONSTRAINT FK_AEA_QUESTION FOREIGN KEY (QUESTION_ID)\n    REFERENCES KONTRATA_EXAM_QUESTION(ID),\n  CONSTRAINT CK_AEA_IS_CORRECT CHECK (IS_CORRECT IN (0, 1))\n);\n\nCREATE INDEX IX_AEA_QUESTION ON KONTRATA_APPLICATION_EXAM_ANSWER (QUESTION_ID);\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_EXAM_ANSWER IS 'Resposta de uma questao dentro de uma tentativa, com a ordem sorteada exibida';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_EXAM_ANSWER.PRESENTED_OPTION_ORDER IS 'JSON: indices das opcoes na ordem sorteada exibida ao candidato';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_EXAM_ANSWER.SELECTED_OPTIONS IS 'JSON: indices (na ordem ORIGINAL da questao) marcados pelo candidato; nulo = nao respondida';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_EXAM_ANSWER.IS_CORRECT IS 'Tudo-ou-nada: 1 so quando o conjunto marcado bate exatamente com o gabarito';\n\n-- Tradução dos códigos de critério (`USU_CODHTE`) da avaliação comportamental\n-- da Senior (`USU_TAVACMP`, ver `senior/service.ts`) pro nome legível — mantida\n-- à mão porque `R079HPE` não é a fonte certa (join removido, ver 0103 anterior\n-- desta feature/commit `416df549`) e a Senior não expôs até agora uma tabela\n-- correta pra isso.\n--\n-- Vive no banco da APLICAÇÃO, não no da Senior: os dois são Oracle separados\n-- sem database link (ver `infra/database/senior/client.ts`), então o\n-- cruzamento código -> label acontece em código, não em SQL — não dá pra\n-- fazer JOIN entre as duas bases.\n--\n-- Sem CREATED_AT/soft-delete: não é catálogo editável pelo recrutador (como\n-- KONTRATA_SKILLS), é tradução fixa de um código que só muda se a Senior\n-- criar/renomear critério — atualização é UPDATE/INSERT manual nesta tabela,\n-- não uma tela.\n--\n-- Spec: conversa 2026-09-11 (lista de códigos passada pelo usuário).\nCREATE TABLE KONTRATA_BEHAVIORAL_CRITERION_LABEL (\n  ID    NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  CODE  VARCHAR2(10)  NOT NULL,\n  LABEL VARCHAR2(200) NOT NULL,\n  CONSTRAINT PK_BEHAVIORAL_CRITERION_LABEL PRIMARY KEY (ID),\n  CONSTRAINT UQ_BEHAVIORAL_CRITERION_LABEL_CODE UNIQUE (CODE)\n);\n\nCOMMENT ON TABLE KONTRATA_BEHAVIORAL_CRITERION_LABEL IS 'Traducao code->label dos criterios de avaliacao comportamental da Senior (USU_CODHTE), mantida a mao';\nCOMMENT ON COLUMN KONTRATA_BEHAVIORAL_CRITERION_LABEL.CODE IS 'USU_CODHTE da Senior (USU_TAVACMP), ex.: 005, 006, 051';\nCOMMENT ON COLUMN KONTRATA_BEHAVIORAL_CRITERION_LABEL.LABEL IS 'Nome legivel do criterio, como fornecido pelo RH/Senior';\n\n-- Resultado de uma tentativa do teste comportamental DISC (INSTRUMENT=DISC,\n-- ANSWER_SCOPE=CANDIDATE): uma linha por tentativa CONCLUÍDA, histórico\n-- preservado (a mais recente é a vigente). EXPIRES_AT é congelado no envio a\n-- partir do VALIDITY_MONTHS do critério NAQUELE MOMENTO — mudar a validade\n-- depois não altera resultado já emitido, mesmo padrão de WEIGHT/\n-- BLOCKS_ADVANCE congelados em KONTRATA_JOB_CRITERION.\n--\n-- MAIN_PROFILE/SECONDARY_PROFILE usam as letras canônicas D/I/S/C\n-- (Dominância/Influência/Estabilidade/Conformidade) — os nomes de\n-- apresentação (Executor/Comunicador/Planejador/Analista) ficam só em\n-- código (infra/matching/criteria/disc-content.ts).\n--\n-- Spec: docs/superpowers/specs/2026-09-18-teste-disc-design.md\nCREATE TABLE KONTRATA_CANDIDATE_DISC_RESULT (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  CANDIDATE_ID NUMBER NOT NULL,\n  STARTED_AT TIMESTAMP NOT NULL,\n  SUBMITTED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  EXPIRES_AT TIMESTAMP NOT NULL,\n  D_MORE_COUNT NUMBER(2) NOT NULL,\n  D_LESS_COUNT NUMBER(2) NOT NULL,\n  D_FINAL NUMBER(3) NOT NULL,\n  D_PCT NUMBER(5,2) NOT NULL,\n  I_MORE_COUNT NUMBER(2) NOT NULL,\n  I_LESS_COUNT NUMBER(2) NOT NULL,\n  I_FINAL NUMBER(3) NOT NULL,\n  I_PCT NUMBER(5,2) NOT NULL,\n  S_MORE_COUNT NUMBER(2) NOT NULL,\n  S_LESS_COUNT NUMBER(2) NOT NULL,\n  S_FINAL NUMBER(3) NOT NULL,\n  S_PCT NUMBER(5,2) NOT NULL,\n  C_MORE_COUNT NUMBER(2) NOT NULL,\n  C_LESS_COUNT NUMBER(2) NOT NULL,\n  C_FINAL NUMBER(3) NOT NULL,\n  C_PCT NUMBER(5,2) NOT NULL,\n  MAIN_PROFILE VARCHAR2(1) NOT NULL,\n  SECONDARY_PROFILE VARCHAR2(1),\n  CONSTRAINT PK_CAND_DISC_RESULT PRIMARY KEY (ID),\n  CONSTRAINT FK_CDR_CANDIDATE FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES(ID) ON DELETE CASCADE,\n  CONSTRAINT CK_CDR_MAIN_PROFILE CHECK (MAIN_PROFILE IN ('D','I','S','C')),\n  CONSTRAINT CK_CDR_SECONDARY_PROFILE\n    CHECK (SECONDARY_PROFILE IS NULL OR SECONDARY_PROFILE IN ('D','I','S','C'))\n);\n\nCREATE INDEX IX_CDR_CANDIDATE ON KONTRATA_CANDIDATE_DISC_RESULT (CANDIDATE_ID, SUBMITTED_AT DESC);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_DISC_RESULT IS 'Resultado de uma tentativa concluida do teste DISC, por candidato';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_DISC_RESULT.EXPIRES_AT IS 'Congelado no envio a partir do VALIDITY_MONTHS vigente do criterio -- so historico/informativo, nunca lido para decidir vigencia (ver isExpired em pending.ts)';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_DISC_RESULT.MAIN_PROFILE IS 'Letra D/I/S/C com maior percentual';\nCOMMENT ON COLUMN KONTRATA_CANDIDATE_DISC_RESULT.SECONDARY_PROFILE IS 'Segunda letra, quando a diferenca para a principal e <= 5 pontos';\n\nCREATE TABLE KONTRATA_JOB_PROPOSALS (\n  ID             NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  APPLICATION_ID NUMBER        NOT NULL,\n  SALARY         NUMBER(12,2)  NOT NULL,\n  CONTRACT_TYPE  VARCHAR2(20)  NOT NULL,\n  CONTRACT_NOTE  VARCHAR2(500),\n  START_DATE     DATE          NOT NULL,\n  VALIDITY_DATE  DATE,\n  SENIOR_ESCALA_CODE VARCHAR2(30),\n  WORK_SCHEDULE  VARCHAR2(300),\n  TOKEN          VARCHAR2(36)  NOT NULL,\n  STATUS         VARCHAR2(20)  NOT NULL,\n  CREATED_BY     VARCHAR2(100) NOT NULL,\n  CREATED_AT     TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  RESPONDED_AT   TIMESTAMP,\n  CONSTRAINT PK_JOB_PROPOSALS PRIMARY KEY (ID),\n  CONSTRAINT FK_JOB_PROPOSALS_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT UQ_JOB_PROPOSALS_TOKEN UNIQUE (TOKEN),\n  CONSTRAINT CK_JOB_PROPOSALS_CONTRACT CHECK (\n    CONTRACT_TYPE IN ('CLT','INTERMITTENT','INTERNSHIP','APPRENTICE','TEMPORARY','CONTRACTOR')\n  ),\n  CONSTRAINT CK_JOB_PROPOSALS_STATUS CHECK (\n    STATUS IN ('SENT','ACCEPTED','DECLINED','EXPIRED')\n  )\n);\n\nCREATE INDEX IX_JOB_PROPOSALS_APP ON KONTRATA_JOB_PROPOSALS (APPLICATION_ID, CREATED_AT);\n\nCREATE TABLE KONTRATA_JOB_PROPOSAL_BENEFITS (\n  PROPOSAL_ID   NUMBER        NOT NULL,\n  BENEFIT_CODE  VARCHAR2(30)  NOT NULL,\n  CONSTRAINT PK_JOB_PROPOSAL_BENEFITS PRIMARY KEY (PROPOSAL_ID, BENEFIT_CODE),\n  CONSTRAINT FK_JOB_PROPOSAL_BENEFITS_PROPOSAL FOREIGN KEY (PROPOSAL_ID)\n    REFERENCES KONTRATA_JOB_PROPOSALS (ID) ON DELETE CASCADE,\n  CONSTRAINT CK_JOB_PROPOSAL_BENEFITS_CODE CHECK (\n    BENEFIT_CODE IN (\n      'TRANSPORTE','ALIMENTACAO','SAUDE','ODONTOLOGICO','TELEMEDICINA',\n      'FARMACIA','SEGURO_VIDA','PLR','CRECHE','AUXILIO_EDUCACAO'\n    )\n  )\n);\n\n-- Resposta a um bloco do teste DISC. A palavra escolhida (ex.: \"Determinado\")\n-- e derivavel do numero do bloco + letra no codigo fixo\n-- (infra/matching/criteria/disc-content.ts) -- nao precisa de coluna propria.\n--\n-- Spec: docs/superpowers/specs/2026-09-18-teste-disc-design.md\nCREATE TABLE KONTRATA_CANDIDATE_DISC_ANSWER (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  RESULT_ID NUMBER NOT NULL,\n  BLOCK_NUMBER NUMBER(2) NOT NULL,\n  MORE_PROFILE VARCHAR2(1) NOT NULL,\n  LESS_PROFILE VARCHAR2(1) NOT NULL,\n  CONSTRAINT PK_CAND_DISC_ANSWER PRIMARY KEY (ID),\n  CONSTRAINT FK_CDA_RESULT FOREIGN KEY (RESULT_ID)\n    REFERENCES KONTRATA_CANDIDATE_DISC_RESULT(ID) ON DELETE CASCADE,\n  CONSTRAINT UQ_CDA_BLOCK UNIQUE (RESULT_ID, BLOCK_NUMBER),\n  CONSTRAINT CK_CDA_MORE_PROFILE CHECK (MORE_PROFILE IN ('D','I','S','C')),\n  CONSTRAINT CK_CDA_LESS_PROFILE CHECK (LESS_PROFILE IN ('D','I','S','C')),\n  CONSTRAINT CK_CDA_DIFFERENT CHECK (MORE_PROFILE <> LESS_PROFILE)\n);\n\nCOMMENT ON TABLE KONTRATA_CANDIDATE_DISC_ANSWER IS 'Resposta a um bloco do teste DISC; a palavra escolhida e derivavel do bloco+letra em codigo';\n\n-- SENDER_NAME e SENDER_LOGIN guardam coisas diferentes de propósito:\n-- SENDER_NAME é o que aparece pra QUALQUER leitor (nome de exibição do\n-- recrutador, ou nome/e-mail do candidato) -- nunca o login do AD, que o\n-- candidato nao pode ver. SENDER_LOGIN e o samAccountName estavel, so\n-- preenchido para SENDER_TYPE='RECRUITER', usado so no lado recrutador para\n-- decidir \"e minha mensagem\" quando mais de um recrutador manda mensagem na\n-- mesma candidatura -- nome de exibicao sozinho nao serve pra essa\n-- comparacao (dois recrutadores podem ter o mesmo nome, e o nome pode\n-- truncar diferente do que o AD guarda). Nunca sai da API para o candidato.\nCREATE TABLE KONTRATA_APPLICATION_MESSAGES (\n  ID             NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  APPLICATION_ID NUMBER        NOT NULL,\n  SENDER_TYPE    VARCHAR2(20)  NOT NULL,\n  SENDER_NAME    VARCHAR2(100) NOT NULL,\n  SENDER_LOGIN   VARCHAR2(100),\n  BODY           CLOB          NOT NULL,\n  CREATED_AT     TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_APPLICATION_MESSAGES PRIMARY KEY (ID),\n  CONSTRAINT FK_APPLICATION_MESSAGES_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT CK_APPLICATION_MESSAGES_SENDER_TYPE CHECK (\n    SENDER_TYPE IN ('CANDIDATE','RECRUITER')\n  )\n);\n\nCREATE INDEX IX_APPLICATION_MESSAGES_APP ON KONTRATA_APPLICATION_MESSAGES (APPLICATION_ID, CREATED_AT);\n\nCREATE TABLE KONTRATA_APPLICATION_MESSAGE_READS (\n  APPLICATION_ID   NUMBER        NOT NULL,\n  PARTICIPANT_TYPE VARCHAR2(20)  NOT NULL,\n  LAST_READ_AT     TIMESTAMP     NOT NULL,\n  CONSTRAINT PK_APPLICATION_MESSAGE_READS PRIMARY KEY (APPLICATION_ID, PARTICIPANT_TYPE),\n  CONSTRAINT FK_APPLICATION_MESSAGE_READS_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT CK_APPLICATION_MESSAGE_READS_TYPE CHECK (\n    PARTICIPANT_TYPE IN ('CANDIDATE','RECRUITER')\n  )\n);\n\n-- Convite de candidatura: candidato precisa aceitar antes da candidatura\n-- nascer, quando ela é criada/redirecionada por iniciativa do recrutador\n-- sobre um candidato que já tem conta. Ver design em\n-- docs/superpowers/specs/2026-09-23-convite-aceite-transferencia-candidato-design.md.\n--\n-- TARGET_STAGE_ID e SOURCE_APPLICATION_ID nascem sempre NULL nesta fase\n-- (convite de inserção direta) — a feature de transferência entre vagas\n-- (plano separado, construído em cima deste) é quem os preenche.\n--\n-- EXPIRED só é gravado quando um convite novo pro mesmo (candidato, vaga)\n-- substitui um SENT vencido (`createInvite`), liberando UX_APP_INVITES_PENDING.\n-- Sem sweep: um SENT vencido que ninguém substituiu continua SENT no banco, e\n-- a leitura deriva EXPIRED pelo EXPIRES_AT.\n--\n-- Transferência pedida por quem não é da matriz nasce PENDING_APPROVAL (sem\n-- e-mail, invisível ao candidato) e vira SENT ao ser aprovada ou REJECTED ao\n-- ser recusada. PENDING_APPROVAL não expira sozinho: a aprovação pode trocar\n-- EXPIRES_AT. Vira CANCELED quando o solicitante desiste ou quando a\n-- candidatura de origem é contratada ou transferida por outro caminho.\n\nCREATE TABLE KONTRATA_APPLICATION_INVITES (\n  ID                     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  CANDIDATE_ID           NUMBER        NOT NULL,\n  JOB_ID                 NUMBER        NOT NULL,\n  TARGET_STAGE_ID        NUMBER,\n  SOURCE_APPLICATION_ID  NUMBER,\n  TOKEN                  VARCHAR2(36)  NOT NULL,\n  STATUS                 VARCHAR2(20)  NOT NULL,\n  NOTE                   CLOB,\n  CRITERIA_ANSWERS       CLOB,\n  CREATED_BY             VARCHAR2(100) NOT NULL,\n  CREATED_AT             TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,\n  RESPONDED_AT           TIMESTAMP,\n  EXPIRES_AT             TIMESTAMP     NOT NULL,\n  APPROVED_BY            VARCHAR2(100),\n  APPROVED_AT            TIMESTAMP,\n  REJECTED_BY            VARCHAR2(100),\n  REJECTED_AT            TIMESTAMP,\n  REJECTION_REASON       VARCHAR2(500),\n  CANCELED_BY            VARCHAR2(100),\n  CANCELED_AT            TIMESTAMP,\n  CANCEL_REASON          VARCHAR2(500),\n  CONSTRAINT PK_APP_INVITES PRIMARY KEY (ID),\n  CONSTRAINT FK_APP_INVITES_CAND FOREIGN KEY (CANDIDATE_ID)\n    REFERENCES KONTRATA_CANDIDATES (ID),\n  CONSTRAINT FK_APP_INVITES_JOB FOREIGN KEY (JOB_ID)\n    REFERENCES KONTRATA_JOBS (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_APP_INVITES_STAGE FOREIGN KEY (TARGET_STAGE_ID)\n    REFERENCES KONTRATA_STAGE (ID),\n  CONSTRAINT FK_APP_INVITES_SOURCE FOREIGN KEY (SOURCE_APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT UQ_APP_INVITES_TOKEN UNIQUE (TOKEN),\n  CONSTRAINT CK_APP_INVITES_STATUS CHECK (STATUS IN ('SENT','ACCEPTED','DECLINED','EXPIRED','PENDING_APPROVAL','REJECTED','CANCELED'))\n);\n\nCREATE INDEX IX_APP_INVITES_JOB ON KONTRATA_APPLICATION_INVITES (JOB_ID, CREATED_AT);\n\n-- No máximo um convite em aberto (SENT ou PENDING_APPROVAL) por (candidato,\n-- vaga) — índice único funcional, mesma técnica de UX_APP_HIST_INSCRICAO:\n-- Oracle não indexa NULL, então linha fechada produz NULL e fica de fora.\nCREATE UNIQUE INDEX UX_APP_INVITES_PENDING ON KONTRATA_APPLICATION_INVITES (\n  CASE WHEN STATUS IN ('SENT','PENDING_APPROVAL') THEN CANDIDATE_ID END,\n  CASE WHEN STATUS IN ('SENT','PENDING_APPROVAL') THEN JOB_ID END\n);\n\n-- No máximo uma transferência em aberto (SENT ou PENDING_APPROVAL) por\n-- candidatura de origem. Convite de inserção direta tem SOURCE_APPLICATION_ID\n-- NULL e fica de fora.\nCREATE UNIQUE INDEX UX_APP_INVITES_SOURCE ON KONTRATA_APPLICATION_INVITES (\n  CASE WHEN STATUS IN ('SENT','PENDING_APPROVAL') THEN SOURCE_APPLICATION_ID END\n);\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_INVITES IS 'Convite de candidatura pendente de aceite do candidato';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_INVITES.TARGET_STAGE_ID IS 'NULL = nasce na primeira etapa do fluxo (inserção direta); preenchido = etapa específica (transferência)';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_INVITES.SOURCE_APPLICATION_ID IS 'Candidatura de origem, só em convite de transferência entre vagas. ON DELETE CASCADE: apagar essa candidatura (nunca acontece pela aplicação, só limpeza manual de dev/hml) apaga o convite junto — é o próprio registro da transferência, não faz sentido órfão.';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_INVITES.NOTE IS 'Motivo do recrutador, interno — nunca exposto ao candidato';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_INVITES.CRITERIA_ANSWERS IS 'JSON com respostas de critério bloqueante staged até o aceite, mesma forma de CriterionAnswerInput';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_INVITES.REJECTION_REASON IS 'Motivo da matriz ao recusar a transferência (STATUS = REJECTED)';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_INVITES.CANCELED_BY IS 'Quem cancelou a transferência pendente (STATUS = CANCELED), ou SYSTEM no cancelamento automático';\n\n-- Acesso de uma pessoa do AD ao portal do recrutador. Sem linha = sem acesso.\n-- Super admins vem de env (KONTRATA_SUPER_ADMINS) e nunca tem linha aqui.\n-- Spec: docs/superpowers/specs/2026-09-29-controle-acesso-features-design.md\n\nCREATE TABLE KONTRATA_USER_ACCESS (\n  ID               NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  SAM_ACCOUNT_NAME VARCHAR2(100) NOT NULL,\n  --\n  ALL_FILIAIS      NUMBER(1) DEFAULT 0 NOT NULL,\n  ALL_STAGES       NUMBER(1) DEFAULT 1 NOT NULL,\n  --\n  CREATED_BY       VARCHAR2(100) NOT NULL,\n  CREATED_AT       TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_BY       VARCHAR2(100) NOT NULL,\n  UPDATED_AT       TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_USER_ACCESS PRIMARY KEY (ID),\n  CONSTRAINT UQ_USER_ACCESS_SAM UNIQUE (SAM_ACCOUNT_NAME),\n  CONSTRAINT CK_USER_ACCESS_ALL_FILIAIS CHECK (ALL_FILIAIS IN (0,1)),\n  CONSTRAINT CK_USER_ACCESS_ALL_STAGES CHECK (ALL_STAGES IN (0,1)),\n  CONSTRAINT CK_USER_ACCESS_SAM_LOWER CHECK (SAM_ACCOUNT_NAME = LOWER(SAM_ACCOUNT_NAME))\n);\n\n-- Features concedidas. FEATURE_KEY sem CHECK: o conjunto fechado vive em\n-- apps/api/src/shared/access/features.ts, e chave fora dele e ignorada na leitura.\n\nCREATE TABLE KONTRATA_USER_FEATURE (\n  ID               NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  USER_ACCESS_ID   NUMBER        NOT NULL,\n  FEATURE_KEY      VARCHAR2(60)  NOT NULL,\n  CONSTRAINT PK_USER_FEATURE PRIMARY KEY (ID),\n  CONSTRAINT UQ_USER_FEATURE UNIQUE (USER_ACCESS_ID, FEATURE_KEY),\n  CONSTRAINT FK_USER_FEATURE_ACCESS FOREIGN KEY (USER_ACCESS_ID)\n    REFERENCES KONTRATA_USER_ACCESS (ID) ON DELETE CASCADE\n);\n\n-- Filiais do escopo, lidas so quando KONTRATA_USER_ACCESS.ALL_FILIAIS = 0.\n-- Par codigo + nome (snapshot da Senior), como toda referencia a Senior.\n\nCREATE TABLE KONTRATA_USER_FILIAL (\n  ID               NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  USER_ACCESS_ID   NUMBER        NOT NULL,\n  FILIAL_CODE      VARCHAR2(10)  NOT NULL,\n  FILIAL_NAME      VARCHAR2(255) NOT NULL,\n  CONSTRAINT PK_USER_FILIAL PRIMARY KEY (ID),\n  CONSTRAINT UQ_USER_FILIAL UNIQUE (USER_ACCESS_ID, FILIAL_CODE),\n  CONSTRAINT FK_USER_FILIAL_ACCESS FOREIGN KEY (USER_ACCESS_ID)\n    REFERENCES KONTRATA_USER_ACCESS (ID) ON DELETE CASCADE\n);\n\n-- Etapas do catalogo no escopo, lidas so quando ALL_STAGES = 0.\n\nCREATE TABLE KONTRATA_USER_STAGE (\n  ID               NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  USER_ACCESS_ID   NUMBER        NOT NULL,\n  STAGE_ID         NUMBER        NOT NULL,\n  CONSTRAINT PK_USER_STAGE PRIMARY KEY (ID),\n  CONSTRAINT UQ_USER_STAGE UNIQUE (USER_ACCESS_ID, STAGE_ID),\n  CONSTRAINT FK_USER_STAGE_ACCESS FOREIGN KEY (USER_ACCESS_ID)\n    REFERENCES KONTRATA_USER_ACCESS (ID) ON DELETE CASCADE,\n  CONSTRAINT FK_USER_STAGE_STAGE FOREIGN KEY (STAGE_ID)\n    REFERENCES KONTRATA_STAGE (ID)\n);\n\nCREATE INDEX IX_USER_STAGE_STAGE ON KONTRATA_USER_STAGE (STAGE_ID);\n\n-- Dados contratuais que so o recrutador informa (posto, centro de custo,\n-- turma, experiencia, tipo de admissao, sindicato, forma de pagamento) e o\n-- retrato congelado do pacote de admissao enviado a Senior. Uma linha por\n-- candidatura; nasce no primeiro PUT.\nCREATE TABLE KONTRATA_APPLICATION_ADMISSION (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  APPLICATION_ID NUMBER NOT NULL,\n  SENIOR_POSTO_CODE VARCHAR2(30),\n  SENIOR_POSTO_NAME VARCHAR2(255),\n  SENIOR_CCU_CODE VARCHAR2(30),\n  SENIOR_CCU_NAME VARCHAR2(255),\n  SENIOR_TURMA_CODE NUMBER,\n  SALARY_TYPE VARCHAR2(10),\n  EXPERIENCE_DAYS NUMBER(4),\n  EXPERIENCE_EXTENSION_DAYS NUMBER(4),\n  ADMISSION_TYPE VARCHAR2(30),\n  SENIOR_BAIRRO_CODE NUMBER,\n  SENIOR_BAIRRO_NAME VARCHAR2(120),\n  SENIOR_SINDICATO_CODE NUMBER,\n  SENIOR_SINDICATO_NAME VARCHAR2(255),\n  PAYMENT_MODE VARCHAR2(1),\n--\n  FROZEN_PACKAGE CLOB,\n  FROZEN_AT TIMESTAMP,\n  FROZEN_BY VARCHAR2(100),\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  UPDATED_BY VARCHAR2(100),\n  CONSTRAINT PK_APP_ADMISSION PRIMARY KEY (ID),\n  CONSTRAINT UQ_APP_ADMISSION_APP UNIQUE (APPLICATION_ID),\n  CONSTRAINT FK_APP_ADMISSION_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT CK_APP_ADMISSION_FROZEN CHECK (\n    (FROZEN_AT IS NULL AND FROZEN_BY IS NULL) OR (FROZEN_AT IS NOT NULL AND FROZEN_BY IS NOT NULL)\n  )\n);\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_ADMISSION IS 'Dados contratuais do recrutador e pacote de admissao congelado para a Senior';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION.SENIOR_POSTO_CODE IS 'R017POS.POSTRA; padrao = posto unico da R017CAR para filial+setor+cargo';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION.SENIOR_CCU_CODE IS 'R018CCU.CODCCU; padrao = 2 (Identificado)';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION.SALARY_TYPE IS 'MONTHLY|HOURLY, vira R034FUN.TIPSAL 1|2';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION.ADMISSION_TYPE IS 'FIRST_JOB|REHIRE|TRANSFER_WITH_COST|TRANSFER_WITHOUT_COST|MERGER|REINSTATEMENT, vira R034FUN.TIPADM 1 a 6';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION.SENIOR_BAIRRO_CODE IS 'R074BAI.CODBAI fixado a mao quando o nome do bairro nao casa; NULL = casamento automatico';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION.SENIOR_SINDICATO_CODE IS 'R014SIN.CODSIN; padrao = sindicato mais comum dos ativos com a mesma filial e cargo (R038HSI)';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION.PAYMENT_MODE IS 'C|R|D|O|P do web service fichaBasica.modPag; padrao R';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION.FROZEN_PACKAGE IS 'JSON do pacote de admissao conferido pelo RH; imutavel depois de INTEGRACAO_SENIOR';\n\n-- Dados da contratacao que o candidato informa na etapa Documentacao de\n-- Admissao, um registro por candidatura. Raca/cor e deficiencia moram aqui e\n-- nao no perfil: aqui a base legal e obrigacao legal (LGPD art. 11, II, a),\n-- no perfil e consentimento (art. 11, I).\nCREATE TABLE KONTRATA_APPLICATION_ADMISSION_FORM (\n  ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,\n  APPLICATION_ID NUMBER NOT NULL,\n  RACE_CODE VARCHAR2(10),\n  HAS_DISABILITY NUMBER(1),\n  DISABILITY_CODES VARCHAR2(40),\n  USES_TRANSPORT_VOUCHER NUMBER(1),\n  FIRST_JOB VARCHAR2(10),\n  SUBMITTED_AT TIMESTAMP,\n  UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n  CONSTRAINT PK_APP_ADMISSION_FORM PRIMARY KEY (ID),\n  CONSTRAINT UQ_APP_ADMISSION_FORM_APP UNIQUE (APPLICATION_ID),\n  CONSTRAINT FK_APP_ADMISSION_FORM_APP FOREIGN KEY (APPLICATION_ID)\n    REFERENCES KONTRATA_JOB_APPLICATIONS (ID) ON DELETE CASCADE,\n  CONSTRAINT CK_APP_ADMISSION_FORM_PCD CHECK (HAS_DISABILITY IN (0, 1)),\n  CONSTRAINT CK_APP_ADMISSION_FORM_VT CHECK (USES_TRANSPORT_VOUCHER IN (0, 1))\n);\n\nCOMMENT ON TABLE KONTRATA_APPLICATION_ADMISSION_FORM IS 'Dados da contratacao informados pelo candidato na Documentacao de Admissao';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION_FORM.RACE_CODE IS 'BRANCA|PRETA|AMARELA|PARDA|INDIGENA (R010ETN via mappings.ts)';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION_FORM.DISABILITY_CODES IS 'Codigos R022DEF separados por virgula; so com HAS_DISABILITY = 1';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION_FORM.FIRST_JOB IS 'YES|NO, conjunto fechado no codigo';\nCOMMENT ON COLUMN KONTRATA_APPLICATION_ADMISSION_FORM.SUBMITTED_AT IS 'Quando o candidato enviou o cadastro completo para analise; NULL = rascunho';"
